function toast(title,message='',actions=[]){
  const el=document.createElement('div');el.className='toast';el.innerHTML=`<strong>${esc(title)}</strong>${message?`<p>${esc(message)}</p>`:''}${actions.length?`<div class="toast-actions">${actions.map((a,i)=>`<button data-i="${i}">${esc(a.label)}</button>`).join('')}</div>`:''}`;
  $('toastStack').appendChild(el); actions.forEach((a,i)=>el.querySelector(`[data-i="${i}"]`)?.addEventListener('click',()=>{a.onClick?.();el.remove();})); setTimeout(()=>el.remove(),actions.length?10000:4200);
}
function setSafeMode(message,error=null){safeMode=true;$('app').hidden=true;$('lockScreen').hidden=true;$('safeScreen').hidden=false;$('safeModeMessage').textContent=message||t('safeModeText');if(error)console.error(error);}
function leaveSafeMode(){safeMode=false;$('safeScreen').hidden=true;$('app').hidden=false;}
function openModal(html,{wide=false,onOpen=null}={}){const wasHidden=$('modalBackdrop').hidden;if(wasHidden)history.pushState({ledgerlyModal:true},'',location.href);$('modal').className='modal'+(wide?' wide':'');$('modal').innerHTML=html;$('modalBackdrop').hidden=false;document.body.style.overflow='hidden';onOpen?.();}
function closeModal(fromPop=false){const wasOpen=!$('modalBackdrop').hidden;$('modalBackdrop').hidden=true;$('modal').innerHTML='';document.body.style.overflow='';ui.modal=null;if(wasOpen&&!fromPop&&history.state?.ledgerlyModal)history.back();}
function modalFrame(title,subtitle,body){return `<div class="modal-head"><div><h2>${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div><button class="modal-close" type="button" data-action="close-modal" aria-label="Close">×</button></div><div class="modal-body">${body}</div>`;}
function confirmModal({title='Confirm',text='',confirm='Confirm',danger=false,onConfirm}){ui.modal={type:'confirm',onConfirm};openModal(modalFrame(title,'',`<div class="${danger?'danger-box':'notice'}">${esc(text)}</div><div class="form-actions"><button class="btn btn-soft" data-action="close-modal" type="button">${t('cancel')}</button><button class="btn ${danger?'btn-danger':'btn-primary'}" data-action="confirm-modal" type="button">${esc(confirm)}</button></div>`));}

function confirmAsync({title='Confirm',text='',confirm='Continue',danger=false}){return new Promise(resolve=>{ui.modal={type:'confirmAsync',resolve};openModal(modalFrame(title,'',`<div class="${danger?'danger-box':'notice'}">${esc(text)}</div><div class="form-actions"><button class="btn btn-soft" data-action="confirm-async-no" type="button">${t('cancel')}</button><button class="btn ${danger?'btn-danger':'btn-primary'}" data-action="confirm-async-yes" type="button">${esc(confirm)}</button></div>`));});}
function money(h){return formatSAR(Number(h||0),ui.privacy!=='none');}
function rawMoney(h){return formatSAR(Number(h||0),false);}
function applyPrivacy(){document.body.classList.toggle('privacy-amounts',ui.privacy==='amounts');document.body.classList.toggle('privacy-all',ui.privacy==='all');}
function applyTheme(){const pref=state?.settings?.theme||'system';const dark=pref==='dark'||(pref==='system'&&matchMedia('(prefers-color-scheme:dark)').matches);document.body.classList.toggle('dark',dark);$('themeBtn').textContent=dark?'☀':'☾';$('themeColorMeta').content=dark?'#0d1412':'#0d2f28';}
function applyLanguage(){setLanguage('en');document.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=t(el.dataset.i18n));$('searchInput').placeholder=t('search');}
function applyReduceMotion(){document.body.classList.toggle('reduce-motion',Boolean(state?.settings?.reduceMotion));}
function updateConnectivity(){const on=navigator.onLine;$('connectivityDot').classList.toggle('offline',!on);$('connectivityLabel').textContent=on?t('online'):t('offline');}

async function buildRecordFromState(nextState,nextRevision){
  if(record?.encrypted){if(!dek)throw new Error('Ledger is locked.');const envelope=await encryptJson(nextState,dek);return {id:'current',encrypted:true,revision:nextRevision,envelope,security};}
  return {id:'current',encrypted:false,revision:nextRevision,payload:nextState,security:null};
}
async function appendAudit(target,{event,entityType='system',entityId=null,creditorId=null,details='',before=null,after=null,reason=''}){
  const prev=(target.audit||[])[0]?.hash||'';const entry={id:uid('audit'),ts:nowIso(),event,entityType,entityId,creditorId,details,before,after,reason,prevHash:prev,hash:null,appVersion:APP_VERSION};
  entry.hash=await sha256Text(JSON.stringify({...entry,hash:null}));target.audit=[entry,...(target.audit||[])];target.auditArchive=target.auditArchive||[];if(target.audit.length>500){const archived=target.audit.splice(500);target.auditArchive=[...archived,...target.auditArchive];}return entry;
}
async function commit({event,details='',entityType='system',entityId=null,creditorId=null,reason='',snapshotReason=null,mutate}){
  if(safeMode)throw new Error('Ledger is in safe mode.'); if(!state)throw new Error('Ledger is locked.');
  const beforeState=deepClone(state);const expected=Number(record?.revision||state.meta?.revision||0);const operationId=await beginOperation({type:event,reason,expectedRevision:expected});
  try{
    const next=deepClone(state);await mutate(next);next.meta={...(next.meta||{}),revision:expected+1,updatedAt:nowIso(),appVersion:APP_VERSION};
    await appendAudit(next,{event,entityType,entityId,creditorId,details,reason,before:null,after:null});validateState(reconcileState(next));
    const nextRecord=await buildRecordFromState(next,expected+1);const saved=await saveStateRecord(nextRecord,{expectedRevision:expected,snapshotReason:snapshotReason||`Before: ${event}`,operationId});
    state=reconcileState(next);state.meta.revision=saved.revision;record=saved;lastWriteAt=Date.now();render();return true;
  }catch(err){state=beforeState;await failOperation(operationId,err).catch(()=>{});if(err instanceof RevisionConflictError){await reloadFromStorage();toast('Newer data detected','Ledgerly loaded the latest revision instead of overwriting it.');return false;}throw err;}
}
async function reloadFromStorage(){const r=await getStateRecord();if(!r)return;if(r.encrypted){record=r;security=r.security;if(dek){try{state=reconcileState(await decryptJson(r.envelope,dek));render();}catch{lockApp();}}}else{record=r;state=reconcileState(r.payload);render();}}

function armAutoLock(){clearTimeout(idleTimer);if(!record?.encrypted||!dek)return;const mins=Math.max(1,Number(state?.settings?.autoLockMinutes||security?.autoLockMinutes||15));idleTimer=setTimeout(lockApp,mins*60000);}
function lockApp(){if(!record?.encrypted)return;dek=null;state=null;clearTimeout(idleTimer);$('app').hidden=true;$('lockScreen').hidden=false;setTimeout(()=>$('unlockPassword')?.focus(),50);}
function unlockUi(){clearTimeout(idleTimer);$('lockScreen').hidden=true;$('app').hidden=false;leaveSafeMode();armAutoLock();}

async function bootstrap(){
  $('versionLabel').textContent=`v${APP_VERSION} · ${BUILD_ID}`;$('footerVersion').textContent=`v${APP_VERSION}`;setupStaticEvents();setupServiceWorker();updateConnectivity();
  const persist=await requestPersistentStorage();storageInfo=await storageEstimate();storageInfo.persisted=persist.persisted||storageInfo.persisted;backupMeta=(await getMeta('backup'))?.value||backupMeta;
  record=await getStateRecord();
  if(record){localStorage.setItem(INSTALL_MARKER,nowIso());
    security=record.security||null;
    if(record.encrypted){$('app').hidden=true;$('lockScreen').hidden=false;return;}
    try{state=reconcileState(record.payload);validateState(state);unlockUi();render();}
    catch(err){setSafeMode(err.message,err);} return;
  }
  legacyContext=detectLegacy()||await recoverLegacyMirror();
  if(!legacyContext&&localStorage.getItem(INSTALL_MARKER)){setSafeMode('Local Ledgerly data appears to have been removed from browser storage. Do not start a new ledger over it. Restore a verified backup instead.');return;}
  if(legacyContext?.type==='encrypted'){$('app').hidden=true;$('lockScreen').hidden=false;$('unlockError').textContent='Legacy encrypted ledger detected. Enter the existing Ledgerly password to migrate it safely.';return;}
  try{
    if(legacyContext?.type==='plain')state=migrateLegacyState(legacyContext.state);else state=newEmptyState();
    state.meta.revision=1;record=await saveStateRecord({id:'current',encrypted:false,revision:1,payload:state,security:null},{expectedRevision:null,snapshotReason:null});
    localStorage.setItem(INSTALL_MARKER,nowIso());if(legacyContext?.type==='plain'){cleanupLegacyKeys({removePlain:true,removeSecure:false});await clearLegacyDatabase();}unlockUi();render();if(legacyContext)toast('Ledger migrated',`Your existing data is now on Ledgerly ${APP_VERSION}.`);else setTimeout(maybeOnboard,250);
  }catch(err){setSafeMode('Ledgerly could not safely initialize the ledger.',err);}
  const pending=await pendingOperations().catch(()=>[]);if(pending.length)toast('Recovery check',`${pending.length} interrupted operation(s) were detected. Current data remains atomic.`);
}

async function unlockCurrent(secret,{recovery=false}={}){
  try{
    if(legacyContext?.type==='encrypted'&&!record){
      const migrated=await decryptAndMigrateLegacy(legacyContext.envelope,secret);const created=await createSecurity(secret,{withRecovery:true,autoLockMinutes:Number(legacyContext.securityConfig?.autoLockMinutes||15)});security=created.security;dek=created.dek;state=migrated;state.meta.revision=1;const envelope=await encryptJson(state,dek);record=await saveStateRecord({id:'current',encrypted:true,revision:1,envelope,security},{expectedRevision:null});cleanupLegacyKeys();await clearLegacyDatabase();unlockUi();render();showRecoveryKey(created.recoveryKey);legacyContext=null;toast('Migration complete','Existing encrypted data was migrated and re-encrypted safely.');return;
    }
    dek=await unlockSecurity(security,secret,{recovery});
    const decrypted=await decryptJson(record.envelope,dek);
    try{state=reconcileState(decrypted);validateState(state);}catch(validationError){$('lockScreen').hidden=true;setSafeMode(validationError.message,validationError);return;}
    unlockUi();render();$('unlockError').textContent='';
  }catch(err){dek=null;$('unlockError').textContent=recovery?'Recovery key was not accepted.':'Incorrect password or unreadable encrypted ledger.';throw err;}
}

function setupServiceWorker(){
  if(!('serviceWorker'in navigator))return;navigator.serviceWorker.register('./service-worker.js').then(reg=>{
    swRegistration=reg;if(reg.waiting&&navigator.serviceWorker.controller)$('updateBanner').hidden=false;
    reg.addEventListener('updatefound',()=>{const w=reg.installing;if(!w)return;w.addEventListener('statechange',()=>{if(w.state==='installed'&&navigator.serviceWorker.controller)$('updateBanner').hidden=false;});});
    navigator.serviceWorker.addEventListener('controllerchange',()=>location.reload());
  }).catch(console.warn);
}

function visibleCreditorSummaries(){
  const all=state.creditors.filter(c=>!c.archivedAt).map(c=>creditorSummary(state,c.id));const q=normalizeName(ui.search);
  let list=all.filter(s=>{
    if(q&&!normalizeName([s.creditor.name,...(s.creditor.aliases||[]),...(s.creditor.tags||[]),s.creditor.contact?.phone,s.creditor.contact?.email].filter(Boolean).join(' ')).includes(q))return false;
    if(ui.filter==='Outstanding'&&s.status!=='Outstanding')return false;
    if(ui.filter==='Partially Paid'&&s.status!=='Partially Paid')return false;
    if(ui.filter==='Paid'&&s.status!=='Paid')return false;
    if(ui.filter==='Disputed'&&!s.disputed)return false;
    if(ui.filter==='Overdue'&&!s.transactions.some(x=>x.type==='debt'&&x.dueDate&&x.dueDate<todayLocal()&&debtRemaining(state,x.id)>0))return false;
    if(ui.filter==='Due soon'){
      const end=new Date();end.setDate(end.getDate()+30);const endS=end.toISOString().slice(0,10);if(!s.transactions.some(x=>x.type==='debt'&&x.dueDate&&x.dueDate>=todayLocal()&&x.dueDate<=endS&&debtRemaining(state,x.id)>0))return false;
    }
    return true;
  });
  list.sort((a,b)=>{
    if(ui.sort==='name')return a.creditor.name.localeCompare(b.creditor.name);
    if(ui.sort==='updated')return String(b.creditor.updatedAt||'').localeCompare(String(a.creditor.updatedAt||''));
    if(ui.sort==='due')return String(a.nextDue||'9999').localeCompare(String(b.nextDue||'9999'))||b.remaining-a.remaining;
    return b.remaining-a.remaining||a.creditor.name.localeCompare(b.creditor.name);
  });return list;
}

function render(){
  if(!state)return;ui.privacy=state.settings.privacyLevel||'none';applyTheme();applyPrivacy();applyLanguage();applyReduceMotion();updateConnectivity();
  const totals=overallSummary(state);const d=diagnostics(state);const changes=backupMeta.revision==null?Number(state.meta.revision||0):Math.max(0,Number(state.meta.revision||0)-Number(backupMeta.revision||0));
  $('totalRemaining').textContent=money(totals.remaining);$('totalOriginal').textContent=money(totals.liability);$('totalPaid').textContent=money(totals.reductions);$('overallProgress').style.width=`${totals.progress.toFixed(2)}%`;
  $('kpiRemaining').textContent=money(totals.remaining);$('kpiPaid').textContent=money(totals.reductions);$('kpiActive').textContent=String(totals.active);$('kpiProgress').textContent=`${Math.round(totals.progress)}%`;
  $('healthPill').textContent=d.ok?'✓ Reconciled':`⚠ ${d.issues.length} issue${d.issues.length===1?'':'s'}`;$('healthPill').className='health-pill'+(d.ok?'':d.issues.some(i=>i.level==='error')?' bad':' warn');
  $('progressRing').style.setProperty('--angle',`${(totals.progress*3.6).toFixed(2)}deg`);$('ringPercent').textContent=`${Math.round(totals.progress)}%`;$('ringCenter').textContent=`${Math.round(totals.progress)}%`;$('legendPaid').textContent=money(totals.reductions);$('legendRemaining').textContent=money(totals.remaining);
  renderNextAction(totals);renderInsights(totals);renderFilters();renderCreditors();renderActivity();
  $('insightsSection').hidden=!ui.insights;$('toggleInsightsBtn').textContent=ui.insights?t('hideInsights'):t('moreInsights');
  document.title=ui.privacy!=='none'?'Ledgerly · Private Ledger':`Ledgerly · ${rawMoney(totals.remaining)} remaining`;
  const backupText=changes===0?t('backupCurrent'):`${changes} ${t('changesSinceBackup')}`;$('balanceCard').title=backupText;
  armAutoLock();
}

function renderNextAction(totals){
  const active=totals.summaries.filter(s=>s.remaining>0);let title='Keep your ledger current.';let text='Your balances are reconciled. Record the next real payment when it happens.';let action=()=>document.getElementById('creditorsSection').scrollIntoView({behavior:'smooth'});
  const overdue=active.flatMap(s=>s.transactions.filter(tx=>tx.type==='debt'&&tx.dueDate&&debtRemaining(state,tx.id)>0).map(tx=>({s,tx}))).filter(x=>x.tx.dueDate<todayLocal()).sort((a,b)=>a.tx.dueDate.localeCompare(b.tx.dueDate))[0];
  if(overdue){title=`${overdue.s.creditor.name} is overdue.`;text=`A debt record was due ${shortDate(overdue.tx.dueDate)} with ${rawMoney(debtRemaining(state,overdue.tx.id))} still open.`;action=()=>{ui.expanded.add(overdue.s.creditor.id);renderCreditors();document.querySelector(`[data-card-id="${CSS.escape(overdue.s.creditor.id)}"]`)?.scrollIntoView({behavior:'smooth',block:'center'});};}
  else{const unplanned=active.sort((a,b)=>b.remaining-a.remaining).find(s=>!paymentPlanEstimate(state,s.creditor.id));if(unplanned){title=`Give ${unplanned.creditor.name} a plan.`;text=`${rawMoney(unplanned.remaining)} is still open and no planned payment is recorded.`;action=()=>openPlanModal(unplanned.creditor.id);}}
  if(!active.length){title='You are fully clear.';text='Every recorded liability is settled. Keep a verified backup of your ledger.';action=()=>exportBackup();}
  $('nextActionTitle').textContent=title;$('nextActionText').textContent=text;$('nextActionBtn').onclick=action;$('nextActionBtn').textContent=active.length?'Review':'Export backup';
}

function renderInsights(totals){
  const cats=categoryBalances(state);const max=Math.max(...cats.map(c=>c.remaining),1);$('categoryChart').innerHTML=cats.length?cats.map(c=>`<div class="bar-row"><div class="bar-meta"><span>${esc(c.category)}</span><strong class="sensitive">${money(c.remaining)}</strong></div><div class="bar-track"><i style="width:${Math.max(3,c.remaining/max*100).toFixed(1)}%"></i></div></div>`).join(''):'<div class="tx-meta">No category balances yet.</div>';
  const top=[...totals.summaries].filter(s=>s.remaining>0).sort((a,b)=>b.remaining-a.remaining).slice(0,5);$('topOutstanding').innerHTML=top.length?top.map((s,i)=>`<div class="top-item"><span class="rank">${i+1}</span><div><strong class="creditor-name">${esc(s.creditor.name)}</strong><small>${esc(s.status)}</small></div><strong class="top-amount sensitive">${money(s.remaining)}</strong></div>`).join(''):'<div class="tx-meta">No outstanding balances.</div>';
  const hist=monthlyHistory(state,12);const hmax=Math.max(...hist.map(x=>x.remaining),1);$('trendChart').innerHTML=hist.map(x=>`<div class="trend-bar" style="height:${Math.max(3,x.remaining/hmax*100).toFixed(1)}%" data-value="${attr(rawMoney(x.remaining))}"><span>${esc(x.month.slice(5))}</span></div>`).join('');
}

function renderFilters(){const filters=['All','Outstanding','Partially Paid','Paid','Due soon','Overdue','Disputed'];$('filterChips').innerHTML=filters.map(f=>`<button class="chip ${ui.filter===f?'active':''}" data-filter="${attr(f)}" type="button">${esc(f)}</button>`).join('');}

function statusBadge(status){return `<span class="badge ${STATUS_CLASS[status]||''}">${esc(status)}</span>`;}
function qualityBadge(q){return `<span class="badge ${q==='Confirmed'?'ok':q==='Disputed'?'bad':'warn'}">${esc(q||'Confirmed')}</span>`;}
function typeLabel(tx){return ({debt:'Debt',payment:'Payment',adjustment:tx.adjustmentDirection==='decrease'?'Adjustment ↓':'Adjustment ↑',waiver:'Waiver / settlement',reversal:'Reversal'})[tx.type]||tx.type;}
function txAmountClass(tx){const reduction=['payment','waiver'].includes(tx.type)||(tx.type==='adjustment'&&tx.adjustmentDirection==='decrease');return reduction?'credit':'debit';}
function txAmountPrefix(tx){if(tx.type==='payment'||tx.type==='waiver'||(tx.type==='adjustment'&&tx.adjustmentDirection==='decrease'))return '−';if(tx.type==='reversal')return '↺ ';return '+';}

function renderCreditors(){
  const list=visibleCreditorSummaries();$('emptyState').hidden=state.creditors.filter(c=>!c.archivedAt).length>0;$('creditorList').innerHTML=list.map(renderCreditorCard).join('');
}
function renderCreditorCard(s){
  const open=ui.expanded.has(s.creditor.id);const plan=paymentPlanEstimate(state,s.creditor.id);const progress=Math.min(100,Math.max(0,s.progress));
  const txs=[...s.transactions].sort((a,b)=>String(b.effectiveDate).localeCompare(String(a.effectiveDate))||String(b.createdAt).localeCompare(String(a.createdAt)));
  return `<article class="creditor-card" data-card-id="${attr(s.creditor.id)}"><div class="creditor-main">
    <div class="identity"><span class="avatar">${esc(initials(s.creditor.name))}</span><div><div class="creditor-name">${esc(s.creditor.name)}</div><div class="creditor-sub">${s.debtCount} debt record${s.debtCount===1?'':'s'} · ${s.paymentCount} payment${s.paymentCount===1?'':'s'}${s.nextDue?` · due ${esc(shortDate(s.nextDue))}`:''}</div></div></div>
    <div class="metric original-metric"><small>${t('original')}</small><strong class="sensitive">${money(s.liability)}</strong></div><div class="metric"><small>${t('paid')}</small><strong class="paid sensitive">${money(s.reductions)}</strong></div><div class="metric"><small>${t('remaining')}</small><strong class="remain sensitive">${money(s.remaining)}</strong><div class="progress"><i style="width:${progress.toFixed(1)}%"></i></div></div>
    <div class="card-actions"><button class="card-icon" data-action="copy-creditor" data-id="${attr(s.creditor.id)}" type="button" title="Copy summary">⧉</button><button class="card-icon" data-action="toggle-creditor" data-id="${attr(s.creditor.id)}" type="button" aria-expanded="${open}">${open?'−':'＋'}</button></div>
  </div>${open?`<div class="creditor-detail"><div class="balance-strip"><div><small>${t('original')}</small><strong class="sensitive">${money(s.liability)}</strong></div><div><small>${t('paid')}</small><strong class="paid sensitive">${money(s.reductions)}</strong></div><div><small>${t('remaining')}</small><strong class="sensitive" style="color:var(--danger)">${money(s.remaining)}</strong></div></div>
    <div class="mini-actions"><button class="btn btn-primary btn-small" data-action="add-payment" data-id="${attr(s.creditor.id)}" type="button">+ ${t('addPayment')}</button><button class="btn btn-soft btn-small" data-action="add-debt-creditor" data-id="${attr(s.creditor.id)}" type="button">+ ${t('addDebt')}</button><button class="btn btn-soft btn-small" data-action="add-adjustment" data-id="${attr(s.creditor.id)}" type="button">± ${t('addAdjustment')}</button><button class="btn btn-soft btn-small" data-action="add-waiver" data-id="${attr(s.creditor.id)}" type="button">✓ ${t('addWaiver')}</button><button class="btn btn-soft btn-small" data-action="plan" data-id="${attr(s.creditor.id)}" type="button">Plan${plan?` · ${esc(plan.cycles)} cycles`:''}</button><button class="btn btn-soft btn-small" data-action="creditor-menu" data-id="${attr(s.creditor.id)}" type="button">•••</button></div>
    <div class="ledger-list">${txs.length?txs.map(tx=>renderTx(tx,s)).join(''):`<div class="tx-meta">${t('noRecords')}</div>`}</div></div>`:''}</article>`;
}
function renderTx(tx,s){
  const plan=tx.type==='debt'&&Number(tx.plan?.amountHalalas||0)>0?` · plan ${rawMoney(tx.plan.amountHalalas)}/${esc(tx.plan.frequency)}`:'';const allocated=(tx.allocations||[]).reduce((sum,a)=>sum+Number(a.amountHalalas||0),0);const attachCount=Array.isArray(tx.attachmentIds)?tx.attachmentIds.length:0;
  return `<div class="tx-row ${tx.voidedAt?'voided':''}"><div class="tx-top"><div><div class="tx-title">${esc(typeLabel(tx))}${tx.description?` · ${esc(tx.description)}`:''}</div><div class="tx-meta">${esc(shortDate(tx.effectiveDate))} · recorded ${esc(shortDateTime(tx.createdAt))}${plan}</div></div><div class="tx-amount ${txAmountClass(tx)} sensitive">${txAmountPrefix(tx)}${money(tx.amountHalalas)}</div></div>
    <div class="badges">${qualityBadge(tx.quality)}${tx.priority?`<span class="badge">${esc(tx.priority)}</span>`:''}${tx.verified?'<span class="badge ok">✓ Verified</span>':''}${tx.voidedAt?'<span class="badge bad">Voided</span>':''}${tx.type==='payment'&&allocated<tx.amountHalalas?'<span class="badge warn">Partly unallocated</span>':''}${attachCount?`<span class="badge">📎 ${attachCount}</span>`:''}</div>
    ${tx.notes?`<div class="tx-note">${esc(tx.notes)}</div>`:''}${tx.voidedAt&&tx.voidReason?`<div class="tx-note">Void reason: ${esc(tx.voidReason)}</div>`:''}
    <div class="tx-actions"><button class="btn btn-soft btn-small" data-action="edit-tx" data-id="${attr(tx.id)}" type="button">${t('correct')}</button>${!tx.voidedAt?`<button class="btn btn-soft btn-small" data-action="void-tx" data-id="${attr(tx.id)}" type="button">${t('void')}</button>`:''}${['payment','waiver','adjustment'].includes(tx.type)&&!tx.voidedAt?`<button class="btn btn-soft btn-small" data-action="reverse-tx" data-id="${attr(tx.id)}" type="button">${t('reverse')}</button>`:''}${tx.type!=='reversal'?`<button class="btn btn-soft btn-small" data-action="move-tx" data-id="${attr(tx.id)}" type="button">${t('moveRecord')}</button>`:''}<button class="btn btn-soft btn-small" data-action="attachments" data-id="${attr(tx.id)}" type="button">📎 ${t('attachments')}</button></div></div>`;
}

function renderActivity(){
  const month=todayLocal().slice(0,7);const txs=state.transactions.filter(tx=>!tx.voidedAt&&tx.effectiveDate.startsWith(month));const paid=txs.filter(tx=>tx.type==='payment').reduce((s,x)=>s+x.amountHalalas,0);const debts=txs.filter(tx=>tx.type==='debt'||(tx.type==='adjustment'&&tx.adjustmentDirection==='increase')).reduce((s,x)=>s+x.amountHalalas,0);const waived=txs.filter(tx=>tx.type==='waiver').reduce((s,x)=>s+x.amountHalalas,0);$('monthSummaryLabel').textContent=new Date().toLocaleDateString(undefined,{month:'long',year:'numeric'});$('monthSummary').innerHTML=`<div class="month-card"><small>Payments</small><strong class="paid sensitive">${money(paid)}</strong></div><div class="month-card"><small>New debt</small><strong class="sensitive">${money(debts)}</strong></div><div class="month-card"><small>Waived</small><strong class="sensitive">${money(waived)}</strong></div><div class="month-card"><small>Transactions</small><strong>${txs.length}</strong></div>`;
  const audit=(state.audit||[]).slice(0,8);$('activityList').innerHTML=audit.length?audit.map(a=>`<div class="activity-item"><i class="activity-dot"></i><div><strong>${esc(a.event)}</strong><p>${esc(a.details||a.reason||'')}</p></div><time>${esc(shortDateTime(a.ts))}</time></div>`).join(''):'<div class="tx-meta">No activity yet.</div>';
}

function creditorById(id){return state.creditors.find(c=>c.id===id);}
function txById(id){return state.transactions.find(x=>x.id===id);}
function creditorOptions(selected=''){return state.creditors.filter(c=>!c.archivedAt).sort((a,b)=>a.name.localeCompare(b.name)).map(c=>`<option value="${attr(c.id)}" ${c.id===selected?'selected':''}>${esc(c.name)}</option>`).join('');}
function field(label,control,full=false){return `<div class="field ${full?'full':''}"><label>${esc(label)}</label>${control}</div>`;}
function formValue(form,name){return Object.fromEntries(new FormData(form).entries())[name];}

function openAddDebtModal(creditorId=''){
  const fixed=Boolean(creditorId);ui.modal={type:'addDebt',creditorId};const body=`<form id="debtForm" data-draft-id="debt:${attr(creditorId||'new')}"><div class="form-grid">
    ${fixed?`<input type="hidden" name="creditorId" value="${attr(creditorId)}">${field(t('creditor'),`<input value="${attr(creditorById(creditorId)?.name||'')}" disabled>`)}`:`${field(t('creditor'),`<select name="creditorId" id="debtCreditor"><option value="__new__">+ New creditor</option>${creditorOptions()}</select>`)}${field('New creditor name',`<input name="newCreditor" id="newCreditorName" maxlength="100" placeholder="Name">`)}`}
    ${field(`${t('amount')} (SAR)`,`<input name="amount" inputmode="decimal" placeholder="0.00" required>`)}
    ${field(t('effectiveDate'),`<input name="effectiveDate" type="date" value="${todayLocal()}" required>`)}
    ${field(t('dueDate'),`<input name="dueDate" type="date">`)}
    ${field(t('category'),`<input name="category" list="categoryList" value="Personal" maxlength="60"><datalist id="categoryList"><option value="Personal"><option value="Bills & Utilities"><option value="Education"><option value="Housing"><option value="Medical"><option value="Other"></datalist>`)}
    ${field(t('quality'),`<select name="quality"><option>Confirmed</option><option>Estimated</option><option>Disputed</option></select>`)}
    ${field('Verification source',`<input name="verificationSource" maxlength="120" placeholder="Invoice, statement, WhatsApp…">`)}
    ${field('Verified on',`<input name="verifiedAt" type="date">`)}
    ${field(t('priority'),`<select name="priority"><option>High</option><option selected>Medium</option><option>Low</option></select>`)}
    ${field(t('description'),`<input name="description" maxlength="120" placeholder="Debt description">`,true)}
    ${field(t('plannedPayment')+' (SAR)',`<input name="planAmount" inputmode="decimal" placeholder="Optional">`)}
    ${field(t('frequency'),`<select name="planFrequency"><option>Weekly</option><option selected>Monthly</option><option>Quarterly</option></select>`)}
    ${field(t('targetDate'),`<input name="targetDate" type="date">`)}
    ${field(t('notes'),`<textarea name="notes" maxlength="800" placeholder="Optional notes"></textarea>`,true)}
    </div><div class="notice">Financial dates are stored as calendar dates, separate from the time you entered the record. Amounts are stored internally as integer halalas.</div><div class="form-actions"><button class="btn btn-soft" data-action="close-modal" type="button">${t('cancel')}</button><button class="btn btn-primary" type="submit">${t('save')} & lock record</button></div></form>`;
  openModal(modalFrame(t('addDebt'),fixed?creditorById(creditorId)?.name:'Create a new debt record',body),{onOpen:()=>setTimeout(async()=>{const f=document.querySelector('#debtForm');await restoreFormDraft(f);f?.querySelector('input[name="amount"]')?.focus();},30)});
}

async function saveDebt(form){
  const data=Object.fromEntries(new FormData(form).entries());let creditorId=data.creditorId;let creditorName='';let createCreditor=false;
  if(creditorId==='__new__'){creditorName=String(data.newCreditor||'').trim();if(!creditorName)return toast('Name required','Enter the creditor name.');const existing=state.creditors.find(c=>normalizeName(c.name)===normalizeName(creditorName));if(existing)creditorId=existing.id;else{creditorId=uid('cred');createCreditor=true;}}
  const amount=sarToHalalas(data.amount);if(!Number.isSafeInteger(amount)||amount<=0)return toast('Invalid amount','Enter an amount greater than 0.00.');
  const duplicates=duplicateCandidates(state,creditorId,'debt',amount,data.effectiveDate);if(state.settings.duplicateWarnings&&duplicates.length&&!(await confirmAsync({title:'Possible duplicate',text:`A similar debt already exists within 2 days for the same amount (${rawMoney(amount)}). Create another historical record?`,confirm:'Create anyway'})))return;
  await commit({event:'Debt added',entityType:'transaction',creditorId,details:`New debt ${rawMoney(amount)}`,snapshotReason:'Before adding debt',mutate:async next=>{
    if(createCreditor)next.creditors.push({id:creditorId,name:creditorName,normalizedName:normalizeName(creditorName),aliases:[],tags:[],contact:{phone:'',email:''},notes:'',createdAt:nowIso(),updatedAt:nowIso(),archivedAt:null});
    const tx={...txBase({creditorId,type:'debt',amountHalalas:amount,effectiveDate:data.effectiveDate}),category:data.category||'Personal',quality:data.quality||'Confirmed',verificationSource:String(data.verificationSource||'').trim(),verifiedAt:safeDate(data.verifiedAt),priority:data.priority||'Medium',dueDate:safeDate(data.dueDate),description:String(data.description||'').trim()||'Debt record',notes:String(data.notes||'').trim(),plan:{amountHalalas:Math.max(0,sarToHalalas(data.planAmount)||0),frequency:data.planFrequency||'Monthly',nextDate:'',targetDate:safeDate(data.targetDate)}};next.transactions.push(tx);const c=next.creditors.find(x=>x.id===creditorId);if(c)c.updatedAt=nowIso();}});await deleteDraft(form.dataset.draftId).catch(()=>{});closeModal();toast('Debt saved','The original record is preserved in the ledger.');
}

function openPaymentModal(creditorId){
  const s=creditorSummary(state,creditorId);const debts=s.transactions.filter(x=>x.type==='debt'&&!x.voidedAt&&debtRemaining(state,x.id)>0);ui.modal={type:'payment',creditorId};const body=`<form id="paymentForm" data-draft-id="payment:${attr(creditorId)}"><div class="form-grid">
    ${field('Remaining',`<input value="${attr(rawMoney(s.remaining))}" disabled>`)}${field(`${t('amount')} (SAR)`,`<input name="amount" inputmode="decimal" placeholder="0.00" required>`)}
    ${field(t('effectiveDate'),`<input name="effectiveDate" type="date" value="${todayLocal()}" required>`)}${field(t('method'),`<input name="method" maxlength="60" placeholder="Bank transfer, cash…">`)}
    ${field(t('reference'),`<input name="reference" maxlength="100" placeholder="Optional reference">`)}${field('Allocation',`<select name="allocation"><option value="auto">${t('autoAllocate')}</option>${debts.map(d=>`<option value="${attr(d.id)}">Debt ${shortDate(d.effectiveDate)} · ${rawMoney(debtRemaining(state,d.id))}</option>`).join('')}</select>`)}
    ${field(t('notes'),`<textarea name="notes" maxlength="800" placeholder="Optional payment note"></textarea>`,true)}
    <label class="field full"><span><input type="checkbox" name="verified"> ${t('verified')}</span></label>
    </div><div class="form-actions"><button class="btn btn-soft" data-action="close-modal" type="button">${t('cancel')}</button><button class="btn btn-primary" type="submit">${t('save')} payment</button></div></form>`;
  openModal(modalFrame(t('addPayment'),s.creditor.name,body),{onOpen:()=>setTimeout(()=>restoreFormDraft(document.querySelector('#paymentForm')),30)});
}
async function savePayment(form){
  const data=Object.fromEntries(new FormData(form).entries());const creditorId=ui.modal.creditorId;const s=creditorSummary(state,creditorId);const amount=sarToHalalas(data.amount);if(!Number.isSafeInteger(amount)||amount<=0)return toast('Invalid amount','Enter a payment amount greater than zero.');if(amount>s.remaining)return toast('Payment too large',`Maximum remaining is ${rawMoney(s.remaining)}.`);
  const duplicates=duplicateCandidates(state,creditorId,'payment',amount,data.effectiveDate);if(state.settings.duplicateWarnings&&duplicates.length&&!(await confirmAsync({title:'Possible duplicate',text:`A similar payment already exists within 2 days for ${rawMoney(amount)}. Continue?`,confirm:'Create anyway'})))return;
  const preferred=data.allocation&&data.allocation!=='auto'?data.allocation:'';if(preferred&&amount>debtRemaining(state,preferred))return toast('Allocation too large',`That debt record has only ${rawMoney(debtRemaining(state,preferred))} remaining.`);const allocation=preferred?{allocations:[{debtId:preferred,amountHalalas:amount}],unallocated:0}:allocateReduction(state,creditorId,amount,state.settings.autoAllocation||'oldest-first');
  await commit({event:'Payment added',entityType:'transaction',creditorId,details:`Payment ${rawMoney(amount)}`,snapshotReason:'Before adding payment',mutate:async next=>{
    const tx={...txBase({creditorId,type:'payment',amountHalalas:amount,effectiveDate:data.effectiveDate}),description:'Payment',notes:String(data.notes||'').trim(),method:String(data.method||'').trim(),reference:String(data.reference||'').trim(),verified:data.verified==='on',allocations:allocation.allocations,allocationMode:preferred?'specific-debt':state.settings.autoAllocation||'oldest-first'};next.transactions.push(tx);const c=next.creditors.find(x=>x.id===creditorId);if(c)c.updatedAt=nowIso();}});await deleteDraft(form.dataset.draftId).catch(()=>{});closeModal();toast('Payment saved',allocation.unallocated?`${rawMoney(allocation.unallocated)} could not be allocated to a debt record.`:'Payment allocated and reconciled.');
}

function openAdjustmentModal(creditorId){ui.modal={type:'adjustment',creditorId};openModal(modalFrame(t('addAdjustment'),creditorById(creditorId)?.name,`<form id="adjustmentForm"><div class="form-grid">${field('Direction',`<select name="direction"><option value="increase">Increase liability</option><option value="decrease">Decrease liability</option></select>`)}${field(`${t('amount')} (SAR)`,`<input name="amount" inputmode="decimal" required>`)}${field(t('effectiveDate'),`<input name="effectiveDate" type="date" value="${todayLocal()}" required>`)}${field(t('category'),`<input name="category" list="categoryList" value="Personal" maxlength="60"><datalist id="categoryList"><option value="Personal"><option value="Bills & Utilities"><option value="Education"><option value="Housing"><option value="Medical"><option value="Other"></datalist>`)}${field(t('description'),`<input name="description" maxlength="120" placeholder="Fee, correction, charge…">`,true)}${field(t('notes'),`<textarea name="notes" maxlength="800"></textarea>`,true)}</div><div class="notice">Adjustments do not rewrite an old debt. They create a new ledger movement and preserve history.</div><div class="form-actions"><button class="btn btn-soft" data-action="close-modal" type="button">${t('cancel')}</button><button class="btn btn-primary" type="submit">${t('save')} adjustment</button></div></form>`));}
async function saveAdjustment(form){const data=Object.fromEntries(new FormData(form).entries());const amount=sarToHalalas(data.amount);if(!Number.isSafeInteger(amount)||amount<=0)return toast('Invalid amount','Enter a valid amount.');const creditorId=ui.modal.creditorId;const s=creditorSummary(state,creditorId);if(data.direction==='decrease'&&amount>s.remaining)return toast('Adjustment too large','A decrease cannot exceed the current remaining balance.');await commit({event:'Adjustment added',entityType:'transaction',creditorId,details:`${data.direction} ${rawMoney(amount)}`,snapshotReason:'Before adjustment',mutate:async next=>{next.transactions.push({...txBase({creditorId,type:'adjustment',amountHalalas:amount,effectiveDate:data.effectiveDate}),adjustmentDirection:data.direction,category:data.category||'Other',description:String(data.description||'Adjustment').trim(),notes:String(data.notes||'').trim()});}});closeModal();toast('Adjustment saved','History was preserved without rewriting the original debt.');}

function openWaiverModal(creditorId){const s=creditorSummary(state,creditorId);ui.modal={type:'waiver',creditorId};openModal(modalFrame(t('addWaiver'),creditorById(creditorId)?.name,`<form id="waiverForm"><div class="form-grid">${field('Current remaining',`<input value="${attr(rawMoney(s.remaining))}" disabled>`)}${field(`${t('amount')} (SAR)`,`<input name="amount" inputmode="decimal" required>`)}${field(t('effectiveDate'),`<input name="effectiveDate" type="date" value="${todayLocal()}" required>`)}${field(t('description'),`<input name="description" maxlength="120" value="Settlement discount">`)}${field(t('notes'),`<textarea name="notes" maxlength="800" placeholder="Why was this amount waived?"></textarea>`,true)}</div><div class="notice">Use a waiver when a creditor forgives part of the balance. It reduces liability without pretending that money was paid.</div><div class="form-actions"><button class="btn btn-soft" data-action="close-modal" type="button">${t('cancel')}</button><button class="btn btn-primary" type="submit">${t('save')} waiver</button></div></form>`));}
async function saveWaiver(form){const data=Object.fromEntries(new FormData(form).entries());const creditorId=ui.modal.creditorId;const s=creditorSummary(state,creditorId);const amount=sarToHalalas(data.amount);if(!Number.isSafeInteger(amount)||amount<=0||amount>s.remaining)return toast('Invalid amount',`Waiver must be between SAR 0.01 and ${rawMoney(s.remaining)}.`);const alloc=allocateReduction(state,creditorId,amount,state.settings.autoAllocation||'oldest-first');await commit({event:'Waiver added',entityType:'transaction',creditorId,details:`Waived ${rawMoney(amount)}`,reason:String(data.notes||'').trim(),snapshotReason:'Before waiver',mutate:async next=>{next.transactions.push({...txBase({creditorId,type:'waiver',amountHalalas:amount,effectiveDate:data.effectiveDate}),description:String(data.description||'Settlement discount').trim(),notes:String(data.notes||'').trim(),allocations:alloc.allocations,allocationMode:state.settings.autoAllocation||'oldest-first'});}});closeModal();toast('Settlement recorded','The waived amount is separate from actual payments.');}

function authorizeProtected(label,callback){
  if(!record?.encrypted)return callback();
  ui.modal={type:'authorize',label,callback};openModal(modalFrame('Password required',label,`<form id="authorizeForm">${field(t('password'),`<input name="password" type="password" autocomplete="current-password" required>`,true)}<div id="authorizeError" class="form-error"></div><div class="form-actions"><button class="btn btn-soft" data-action="close-modal" type="button">${t('cancel')}</button><button class="btn btn-primary" type="submit">Authorize</button></div></form>`));
}
async function submitAuthorization(form){const password=new FormData(form).get('password');try{await unlockSecurity(security,password,{recovery:false});const cb=ui.modal?.callback;closeModal();await cb?.();}catch{$('authorizeError').textContent='Incorrect master password.';}}

function openEditTx(txId){
  const tx=txById(txId);if(!tx)return;const creditor=creditorById(tx.creditorId);ui.modal={type:'editTx',txId};let fields='';
  if(tx.type==='debt')fields=`${field(`${t('amount')} (SAR)`,`<input name="amount" inputmode="decimal" value="${attr((tx.amountHalalas/100).toFixed(2))}" required>`)}${field(t('effectiveDate'),`<input name="effectiveDate" type="date" value="${attr(tx.effectiveDate)}">`)}${field(t('dueDate'),`<input name="dueDate" type="date" value="${attr(tx.dueDate||'')}">`)}${field(t('category'),`<input name="category" value="${attr(tx.category||'Personal')}" maxlength="60">`)}${field(t('quality'),`<select name="quality"><option ${tx.quality==='Confirmed'?'selected':''}>Confirmed</option><option ${tx.quality==='Estimated'?'selected':''}>Estimated</option><option ${tx.quality==='Disputed'?'selected':''}>Disputed</option></select>`)}${field('Verification source',`<input name="verificationSource" value="${attr(tx.verificationSource||'')}" maxlength="120">`)}${field('Verified on',`<input name="verifiedAt" type="date" value="${attr(tx.verifiedAt||'')}">`)}${field(t('priority'),`<select name="priority"><option ${tx.priority==='High'?'selected':''}>High</option><option ${tx.priority==='Medium'?'selected':''}>Medium</option><option ${tx.priority==='Low'?'selected':''}>Low</option></select>`)}${field(t('description'),`<input name="description" value="${attr(tx.description||'')}" maxlength="120">`,true)}${field(t('plannedPayment')+' (SAR)',`<input name="planAmount" inputmode="decimal" value="${tx.plan?.amountHalalas?(tx.plan.amountHalalas/100).toFixed(2):''}">`)}${field(t('frequency'),`<select name="planFrequency"><option ${tx.plan?.frequency==='Weekly'?'selected':''}>Weekly</option><option ${tx.plan?.frequency==='Monthly'?'selected':''}>Monthly</option><option ${tx.plan?.frequency==='Quarterly'?'selected':''}>Quarterly</option></select>`)}${field(t('targetDate'),`<input name="targetDate" type="date" value="${attr(tx.plan?.targetDate||'')}">`)}${field(t('notes'),`<textarea name="notes" maxlength="800">${esc(tx.notes||'')}</textarea>`,true)}`;
  else if(tx.type==='payment')fields=`${field(`${t('amount')} (SAR)`,`<input name="amount" inputmode="decimal" value="${attr((tx.amountHalalas/100).toFixed(2))}" required>`)}${field(t('effectiveDate'),`<input name="effectiveDate" type="date" value="${attr(tx.effectiveDate)}">`)}${field(t('method'),`<input name="method" value="${attr(tx.method||'')}" maxlength="60">`)}${field(t('reference'),`<input name="reference" value="${attr(tx.reference||'')}" maxlength="100">`)}${field(t('notes'),`<textarea name="notes" maxlength="800">${esc(tx.notes||'')}</textarea>`,true)}<label class="field full"><span><input type="checkbox" name="verified" ${tx.verified?'checked':''}> ${t('verified')}</span></label>`;
  else fields=`${field(`${t('amount')} (SAR)`,`<input name="amount" inputmode="decimal" value="${attr((tx.amountHalalas/100).toFixed(2))}" required>`)}${field(t('effectiveDate'),`<input name="effectiveDate" type="date" value="${attr(tx.effectiveDate)}">`)}${tx.type==='adjustment'?field('Direction',`<select name="direction"><option value="increase" ${tx.adjustmentDirection==='increase'?'selected':''}>Increase</option><option value="decrease" ${tx.adjustmentDirection==='decrease'?'selected':''}>Decrease</option></select>`):''}${field(t('description'),`<input name="description" value="${attr(tx.description||'')}" maxlength="120">`,true)}${field(t('notes'),`<textarea name="notes" maxlength="800">${esc(tx.notes||'')}</textarea>`,true)}`;
  const body=`<div class="danger-box"><strong>Protected correction.</strong> The original history is never silently overwritten. The reason below is written to the audit trail.</div><form id="editTxForm"><div class="form-grid">${fields}${field(t('correctionReason'),`<input name="reason" maxlength="160" required placeholder="Why is this correction necessary?">`,true)}</div><div class="form-actions"><button class="btn btn-soft" data-action="close-modal" type="button">${t('cancel')}</button><button class="btn btn-primary" type="submit">Continue to authorization</button></div></form>`;
  openModal(modalFrame(`${t('correct')} ${typeLabel(tx)}`,creditor?.name||'',body));
}

async function prepareEditTx(form){
  const data=Object.fromEntries(new FormData(form).entries());const txId=ui.modal.txId;const tx=txById(txId);if(!tx)return;const amount=sarToHalalas(data.amount);if(!Number.isSafeInteger(amount)||amount<=0)return toast('Invalid amount','Enter a valid amount.');if(!String(data.reason||'').trim())return toast('Reason required','Explain why the record is being corrected.');
  const payload={...data,amount,reason:String(data.reason).trim(),txId};authorizeProtected(`Correct ${typeLabel(tx)} for ${creditorById(tx.creditorId)?.name}`,()=>applyEditTx(payload));
}
async function applyEditTx(data){
  const current=txById(data.txId);const creditorId=current.creditorId;const before=deepClone(current);
  try{await commit({event:'Transaction corrected',entityType:'transaction',entityId:current.id,creditorId,reason:data.reason,details:`${typeLabel(current)} corrected from ${rawMoney(current.amountHalalas)} to ${rawMoney(data.amount)}`,snapshotReason:'Before protected correction',mutate:async next=>{
    const tx=next.transactions.find(x=>x.id===data.txId);tx.amountHalalas=data.amount;tx.effectiveDate=safeDate(data.effectiveDate)||tx.effectiveDate;tx.description=String(data.description??tx.description??'').trim();tx.notes=String(data.notes??tx.notes??'').trim();tx.modifiedByVersion=APP_VERSION;tx.updatedAt=nowIso();
    if(tx.type==='debt'){tx.dueDate=safeDate(data.dueDate);tx.category=String(data.category||'Personal').trim();tx.quality=data.quality||'Confirmed';tx.verificationSource=String(data.verificationSource||'').trim();tx.verifiedAt=safeDate(data.verifiedAt);tx.priority=data.priority||'Medium';tx.plan={amountHalalas:Math.max(0,sarToHalalas(data.planAmount)||0),frequency:data.planFrequency||'Monthly',nextDate:'',targetDate:safeDate(data.targetDate)};}
    if(tx.type==='payment'){tx.method=String(data.method||'').trim();tx.reference=String(data.reference||'').trim();tx.verified=data.verified==='on';const temp={...next,transactions:next.transactions.filter(x=>x.id!==tx.id)};const alloc=allocateReduction(temp,tx.creditorId,tx.amountHalalas,next.settings.autoAllocation||'oldest-first');tx.allocations=alloc.allocations;tx.allocationMode='correction-auto';}
    if(tx.type==='adjustment')tx.adjustmentDirection=data.direction||tx.adjustmentDirection;
  }});closeModal();toast('Correction saved','The audit trail records the reason and the corrected value.');}catch(err){toast('Correction blocked',err.message||'The correction would make the ledger inconsistent.');}
}

function openVoidTx(txId){const tx=txById(txId);if(!tx||tx.voidedAt)return;ui.modal={type:'voidTx',txId};openModal(modalFrame(`${t('void')} ${typeLabel(tx)}`,creditorById(tx.creditorId)?.name,`<div class="danger-box">Voiding keeps the record in history but removes its financial effect. This action never deletes the historical entry.</div><form id="voidTxForm">${field(t('voidReason'),`<textarea name="reason" maxlength="300" required placeholder="Duplicate, wrong creditor, entered by mistake…"></textarea>`,true)}<div class="form-actions"><button class="btn btn-soft" data-action="close-modal" type="button">${t('cancel')}</button><button class="btn btn-danger" type="submit">Continue to authorization</button></div></form>`));}
async function prepareVoid(form){const reason=String(new FormData(form).get('reason')||'').trim();if(!reason)return toast('Reason required','Enter a reason for voiding the record.');const tx=txById(ui.modal.txId);authorizeProtected(`Void ${typeLabel(tx)} ${rawMoney(tx.amountHalalas)}`,()=>applyVoid(tx.id,reason));}
async function applyVoid(txId,reason){const tx=txById(txId);try{await commit({event:'Transaction voided',entityType:'transaction',entityId:tx.id,creditorId:tx.creditorId,reason,details:`Voided ${typeLabel(tx)} ${rawMoney(tx.amountHalalas)}`,snapshotReason:'Before voiding transaction',mutate:async next=>{const n=next.transactions.find(x=>x.id===txId);n.voidedAt=nowIso();n.voidReason=reason;n.voidedByVersion=APP_VERSION;n.updatedAt=nowIso();}});closeModal();toast('Record voided','The entry remains visible in the historical ledger.');}catch(err){toast('Void blocked',err.message||'Void would break ledger reconciliation. Reverse dependent payments first.');}}

function openReverseTx(txId){const tx=txById(txId);if(!tx)return;if(state.transactions.some(r=>!r.voidedAt&&r.type==='reversal'&&r.reversedTransactionId===txId))return toast('Already reversed','This transaction already has an active reversal.');ui.modal={type:'reverseTx',txId};openModal(modalFrame(t('reverse'),creditorById(tx.creditorId)?.name,`<div class="notice">A reversal creates a new opposite ledger entry. The original record remains unchanged.</div><form id="reverseTxForm">${field(t('reason'),`<textarea name="reason" maxlength="300" required placeholder="Why is this transaction being reversed?"></textarea>`,true)}${field(t('effectiveDate'),`<input name="effectiveDate" type="date" value="${todayLocal()}">`,true)}<div class="form-actions"><button class="btn btn-soft" data-action="close-modal" type="button">${t('cancel')}</button><button class="btn btn-primary" type="submit">Continue to authorization</button></div></form>`));}
async function prepareReverse(form){const data=Object.fromEntries(new FormData(form).entries());if(!String(data.reason||'').trim())return toast('Reason required','Enter the reversal reason.');const tx=txById(ui.modal.txId);authorizeProtected(`Reverse ${typeLabel(tx)} ${rawMoney(tx.amountHalalas)}`,()=>applyReverse(tx.id,data));}
async function applyReverse(txId,data){const target=txById(txId);await commit({event:'Transaction reversed',entityType:'transaction',entityId:target.id,creditorId:target.creditorId,reason:String(data.reason).trim(),details:`Reversal of ${typeLabel(target)} ${rawMoney(target.amountHalalas)}`,snapshotReason:'Before reversal',mutate:async next=>{next.transactions.push({...txBase({creditorId:target.creditorId,type:'reversal',amountHalalas:target.amountHalalas,effectiveDate:data.effectiveDate}),description:`Reversal of ${typeLabel(target)}`,notes:String(data.reason).trim(),reversedTransactionId:target.id,quality:'Confirmed',verified:true});}});closeModal();toast('Reversal recorded','The original transaction was preserved and an opposite entry was added.');}

function openCreditorMenu(creditorId){const c=creditorById(creditorId);const s=creditorSummary(state,creditorId);ui.modal={type:'creditorMenu',creditorId};openModal(modalFrame(c.name,`${rawMoney(s.remaining)} remaining`,`<div class="settings-sections"><div class="settings-card"><h3>Creditor actions</h3><div class="stack-actions"><button class="btn btn-soft" data-action="creditor-details" data-id="${attr(c.id)}" type="button">Edit details & tags</button><button class="btn btn-soft" data-action="rename-creditor" data-id="${attr(c.id)}" type="button">${t('rename')}</button><button class="btn btn-soft" data-action="statement" data-id="${attr(c.id)}" type="button">${t('statement')}</button><button class="btn btn-soft" data-action="merge-creditor" data-id="${attr(c.id)}" type="button">${t('mergeCreditor')}</button><button class="btn btn-soft" data-action="templates-creditor" data-id="${attr(c.id)}" type="button">${t('createTemplate')}</button><button class="btn btn-warning" data-action="archive-creditor" data-id="${attr(c.id)}" type="button">${t('archiveCreditor')}</button></div></div></div>`));}

function openRenameCreditor(id){const c=creditorById(id);ui.modal={type:'renameCreditor',creditorId:id};openModal(modalFrame(t('rename'),c.name,`<form id="renameCreditorForm">${field('New name',`<input name="name" maxlength="100" value="${attr(c.name)}" required>`,true)}${field(t('reason'),`<input name="reason" maxlength="160" value="Name correction" required>`,true)}<div class="form-actions"><button class="btn btn-soft" data-action="close-modal" type="button">${t('cancel')}</button><button class="btn btn-primary" type="submit">Continue to authorization</button></div></form>`));}
async function prepareRename(form){const data=Object.fromEntries(new FormData(form).entries());const name=String(data.name||'').trim();if(!name)return;const duplicate=state.creditors.find(c=>c.id!==ui.modal.creditorId&&normalizeName(c.name)===normalizeName(name));if(duplicate)return toast('Name already exists','Use Merge if these are the same creditor.');const id=ui.modal.creditorId;authorizeProtected(`Rename ${creditorById(id)?.name}`,()=>commit({event:'Creditor renamed',entityType:'creditor',entityId:id,creditorId:id,reason:String(data.reason||'').trim(),details:`Renamed to ${name}`,snapshotReason:'Before creditor rename',mutate:async next=>{const c=next.creditors.find(x=>x.id===id);c.aliases=[...(c.aliases||[]),c.name].slice(-10);c.name=name;c.normalizedName=normalizeName(name);c.updatedAt=nowIso();}}).then(()=>{closeModal();toast('Creditor renamed','Identity and transaction history stayed on the same ID.');}));}

function openMergeCreditor(sourceId){const source=creditorById(sourceId);const targets=state.creditors.filter(c=>!c.archivedAt&&c.id!==sourceId);if(!targets.length)return toast('No merge target','There is no other active creditor to merge into.');ui.modal={type:'mergeCreditor',sourceId};openModal(modalFrame(t('mergeCreditor'),`Move all records from ${source.name} to one existing creditor.`,`<div class="danger-box">The source creditor will be removed after every transaction is reassigned. Nothing in the ledger history is deleted.</div><form id="mergeCreditorForm">${field('Merge into',`<select name="targetId">${targets.map(c=>`<option value="${attr(c.id)}">${esc(c.name)}</option>`).join('')}</select>`,true)}${field(t('reason'),`<input name="reason" maxlength="160" value="Duplicate creditor identity" required>`,true)}<div class="form-actions"><button class="btn btn-soft" data-action="close-modal" type="button">${t('cancel')}</button><button class="btn btn-danger" type="submit">Continue to authorization</button></div></form>`));}
async function prepareMerge(form){const data=Object.fromEntries(new FormData(form).entries());const sourceId=ui.modal.sourceId;const targetId=data.targetId;if(!targetId||targetId===sourceId)return;authorizeProtected(`Merge ${creditorById(sourceId)?.name} into ${creditorById(targetId)?.name}`,()=>applyMerge(sourceId,targetId,String(data.reason||'').trim()));}
async function applyMerge(sourceId,targetId,reason){const source=creditorById(sourceId),target=creditorById(targetId);await commit({event:'Creditors merged',entityType:'creditor',entityId:targetId,creditorId:targetId,reason,details:`Merged ${source.name} into ${target.name}`,snapshotReason:'Before creditor merge',mutate:async next=>{for(const tx of next.transactions)if(tx.creditorId===sourceId){tx.creditorId=targetId;tx.updatedAt=nowIso();tx.modifiedByVersion=APP_VERSION;}const t=next.creditors.find(c=>c.id===targetId);t.aliases=[...(t.aliases||[]),source.name,...(source.aliases||[])].filter(Boolean).slice(-20);t.updatedAt=nowIso();next.creditors=next.creditors.filter(c=>c.id!==sourceId);}});closeModal();ui.expanded.delete(sourceId);ui.expanded.add(targetId);toast('Creditors merged','Every transaction now points to one stable creditor identity.');}

function archiveCreditor(id){const c=creditorById(id);const s=creditorSummary(state,id);confirmModal({title:t('archiveCreditor'),text:s.remaining>0?`${c.name} still has ${rawMoney(s.remaining)} remaining. Archive anyway?`:`Archive ${c.name}? Its history remains searchable in diagnostics and backups.`,confirm:'Archive',danger:s.remaining>0,onConfirm:()=>authorizeProtected(`Archive ${c.name}`,()=>commit({event:'Creditor archived',entityType:'creditor',entityId:id,creditorId:id,details:c.name,snapshotReason:'Before creditor archive',mutate:async next=>{const x=next.creditors.find(c=>c.id===id);x.archivedAt=nowIso();x.updatedAt=nowIso();}}).then(()=>{closeModal();toast('Creditor archived','History is preserved; the creditor is hidden from the active map.');}))});}

function openStatement(id,{redacted=false}={}){const s=creditorSummary(state,id);const name=redacted?'Creditor':s.creditor.name;const rows=[...s.transactions].sort((a,b)=>a.effectiveDate.localeCompare(b.effectiveDate)).map(tx=>`<div class="tx-row ${tx.voidedAt?'voided':''}"><div class="tx-top"><div><div class="tx-title">${esc(typeLabel(tx))}</div><div class="tx-meta">${esc(shortDate(tx.effectiveDate))}${tx.description?` · ${esc(tx.description)}`:''}</div></div><strong class="tx-amount ${txAmountClass(tx)}">${redacted?'••••':txAmountPrefix(tx)+rawMoney(tx.amountHalalas)}</strong></div></div>`).join('');ui.modal={type:'statement',creditorId:id};openModal(modalFrame(`${t('statement')} · ${name}`,`Generated ${shortDateTime(nowIso())}`,`<div class="statement-head"><div><span class="eyebrow">${t('remaining')}</span><div class="statement-total">${redacted?'••••':rawMoney(s.remaining)}</div></div><div><div>${t('original')}: <b>${redacted?'••••':rawMoney(s.liability)}</b></div><div>${t('paid')}: <b>${redacted?'••••':rawMoney(s.reductions)}</b></div></div></div><div class="ledger-list">${rows||'<div class="tx-meta">No transactions.</div>'}</div><div class="form-actions"><button class="btn btn-soft" data-action="statement-redact" data-id="${attr(id)}" type="button">${redacted?'Show full':'Redacted'}</button><button class="btn btn-soft" data-action="copy-creditor" data-id="${attr(id)}" type="button">${t('copySummary')}</button><button class="btn btn-primary" data-action="print" type="button">Print</button></div>`),{wide:true});}

function copyCreditorSummary(id){const s=creditorSummary(state,id);const text=`${s.creditor.name}\nOriginal: ${rawMoney(s.liability)}\nPaid / settled: ${rawMoney(s.reductions)}\nRemaining: ${rawMoney(s.remaining)}\nStatus: ${s.status}`;navigator.clipboard?.writeText(text).then(()=>toast('Copied','Creditor summary copied to clipboard.')).catch(()=>toast('Copy failed','Clipboard permission is unavailable.'));}

function openPlanModal(id){const s=creditorSummary(state,id);const debts=s.transactions.filter(tx=>tx.type==='debt'&&!tx.voidedAt);ui.modal={type:'plan',creditorId:id};const rows=debts.map(d=>`<div class="tx-row"><div class="tx-top"><div><div class="tx-title">${esc(d.description||'Debt')}</div><div class="tx-meta">${rawMoney(debtRemaining(state,d.id))} open · due ${d.dueDate?shortDate(d.dueDate):'not set'}</div></div><button class="btn btn-small btn-soft" data-action="edit-tx" data-id="${attr(d.id)}">Edit plan</button></div><div class="tx-note">Planned: ${d.plan?.amountHalalas?rawMoney(d.plan.amountHalalas)+' / '+d.plan.frequency:'Not set'}${d.plan?.targetDate?' · target '+shortDate(d.plan.targetDate):''}</div></div>`).join('');const estimate=paymentPlanEstimate(state,id);openModal(modalFrame('Plan',s.creditor.name,`<div class="notice">Plans are forecasts only. They never reduce the actual balance until a real payment is recorded.</div>${estimate?`<div class="success-box">At ${rawMoney(estimate.plannedPerCycle)} per cycle, the current balance is about ${estimate.cycles} cycle(s) from zero. Approximate target: ${shortDate(estimate.targetDate)}.</div>`:''}<div class="ledger-list">${rows||'<div class="tx-meta">No debt records.</div>'}</div>`));}

function openTemplatesModal(creditorId=''){const templates=state.templates||[];ui.modal={type:'templates',creditorId};const list=templates.map(tp=>`<div class="tx-row"><div class="tx-top"><div><div class="tx-title">${esc(tp.name)}</div><div class="tx-meta">${esc(creditorById(tp.creditorId)?.name||'Unknown')} · ${rawMoney(tp.amountHalalas)} · ${esc(tp.frequency)} · next ${shortDate(tp.nextDate)}</div></div><button class="btn btn-small btn-primary" data-action="generate-template" data-id="${attr(tp.id)}">Create debt</button></div></div>`).join('');openModal(modalFrame(t('templates'),'Templates never create debts silently.',`${list||'<div class="tx-meta">No templates yet.</div>'}<hr><form id="templateForm"><div class="form-grid">${field('Template name',`<input name="name" maxlength="100" required>`)}${field(t('creditor'),`<select name="creditorId">${creditorOptions(creditorId)}</select>`)}${field(`${t('amount')} (SAR)`,`<input name="amount" inputmode="decimal" required>`)}${field(t('frequency'),`<select name="frequency"><option>Monthly</option><option>Quarterly</option><option>Yearly</option></select>`)}${field('Next date',`<input name="nextDate" type="date" value="${todayLocal()}" required>`)}${field(t('category'),`<input name="category" value="Bills & Utilities">`)}</div><div class="form-actions"><button class="btn btn-primary" type="submit">Save template</button></div></form>`),{wide:true});}
async function saveTemplate(form){const data=Object.fromEntries(new FormData(form).entries());const amount=sarToHalalas(data.amount);if(!amount||amount<=0)return toast('Invalid amount','Enter a valid template amount.');await commit({event:'Recurring template added',entityType:'template',details:data.name,snapshotReason:'Before template change',mutate:async next=>{next.templates.push({id:uid('template'),name:String(data.name).trim(),creditorId:data.creditorId,amountHalalas:amount,frequency:data.frequency,nextDate:safeDate(data.nextDate),category:String(data.category||'Other'),createdAt:nowIso()});}});openTemplatesModal(ui.modal?.creditorId||'');toast('Template saved','It will create a real debt only when you explicitly choose Create debt.');}
async function generateTemplate(id){const tp=state.templates.find(x=>x.id===id);if(!tp)return;confirmModal({title:'Create debt from template?',text:`Create ${rawMoney(tp.amountHalalas)} for ${creditorById(tp.creditorId)?.name} dated ${shortDate(tp.nextDate)}?`,confirm:'Create debt',onConfirm:async()=>{await commit({event:'Debt created from template',entityType:'transaction',creditorId:tp.creditorId,details:tp.name,snapshotReason:'Before template debt creation',mutate:async next=>{next.transactions.push({...txBase({creditorId:tp.creditorId,type:'debt',amountHalalas:tp.amountHalalas,effectiveDate:tp.nextDate}),category:tp.category,description:tp.name,quality:'Confirmed'});const n=next.templates.find(x=>x.id===id);const d=new Date(`${n.nextDate}T12:00:00`);if(n.frequency==='Monthly')d.setMonth(d.getMonth()+1);else if(n.frequency==='Quarterly')d.setMonth(d.getMonth()+3);else d.setFullYear(d.getFullYear()+1);n.nextDate=d.toISOString().slice(0,10);}});closeModal();toast('Debt created','The template remains ready for the next cycle.');}});}

async function sanitizeUpload(file){
  const max=10*1024*1024;if(file.size>max)throw new Error('Attachment exceeds the 10 MB limit.');
  if(!file.type.startsWith('image/'))return {bytes:new Uint8Array(await file.arrayBuffer()),type:file.type||'application/octet-stream',name:file.name};
  let source=null,revoke='';
  try{
    if('createImageBitmap'in globalThis)source=await createImageBitmap(file);
    else{source=await new Promise((resolve,reject)=>{const img=new Image();revoke=URL.createObjectURL(file);img.onload=()=>resolve(img);img.onerror=reject;img.src=revoke;});}
    const width=source.width||source.naturalWidth,height=source.height||source.naturalHeight;const scale=Math.min(1,2200/Math.max(width,height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(width*scale));canvas.height=Math.max(1,Math.round(height*scale));const ctx=canvas.getContext('2d');ctx.drawImage(source,0,0,canvas.width,canvas.height);source.close?.();if(revoke)URL.revokeObjectURL(revoke);const blob=await new Promise(r=>canvas.toBlob(r,'image/jpeg',.9));if(!blob)throw new Error('Image re-encoding failed.');return {bytes:new Uint8Array(await blob.arrayBuffer()),type:'image/jpeg',name:file.name.replace(/\.[^.]+$/,'.jpg')};
  }catch(err){if(revoke)URL.revokeObjectURL(revoke);throw new Error('Ledgerly could not safely strip image metadata. Convert the image to JPG/PNG and try again.');}
}
async function openAttachmentsModal(txId){
  const tx=txById(txId);if(!tx)return;ui.modal={type:'attachments',txId};const items=await listAttachments({transactionId:txId});const rows=items.map(a=>`<div class="tx-row"><div class="tx-top"><div><div class="tx-title">📎 ${esc(a.name||'Attachment')}</div><div class="tx-meta">${esc(a.type||'file')} · ${(Number(a.size||0)/1024).toFixed(0)} KB · ${shortDateTime(a.createdAt)}</div></div><div class="tx-actions"><button class="btn btn-small btn-soft" data-action="download-attachment" data-id="${attr(a.id)}">Open</button><button class="btn btn-small btn-soft" data-action="delete-attachment" data-id="${attr(a.id)}">Remove</button></div></div></div>`).join('');
  openModal(modalFrame(t('attachments'),`${creditorById(tx.creditorId)?.name} · ${typeLabel(tx)}`,`<div class="notice">Images are re-encoded before storage to strip common EXIF metadata such as GPS. Attachments are encrypted when ledger protection is enabled.</div><div class="ledger-list">${rows||'<div class="tx-meta">No attachments yet.</div>'}</div><div class="form-actions"><button class="btn btn-primary" data-action="add-attachment" data-id="${attr(txId)}">+ Add attachment</button></div>`));
}
async function handleAttachmentFile(file){const txId=ui.attachmentTarget;ui.attachmentTarget=null;if(!file||!txId)return;const tx=txById(txId);try{const clean=await sanitizeUpload(file);const est=await storageEstimate();if(est.quota&&est.usage+clean.bytes.byteLength>est.quota*.9)throw new Error('Browser storage is close to its quota. Export a backup and free space before adding this attachment.');const id=uid('att');const meta={id,transactionId:txId,creditorId:tx.creditorId,name:clean.name,type:clean.type,size:clean.bytes.byteLength,createdAt:nowIso(),updatedAt:nowIso(),appVersion:APP_VERSION};const rec=record.encrypted?await encryptAttachmentRecord(meta,clean.bytes,dek):plainAttachmentRecord(meta,clean.bytes);await putAttachment(rec);try{await commit({event:'Attachment added',entityType:'attachment',entityId:id,creditorId:tx.creditorId,details:clean.name,snapshotReason:'Before attachment link',mutate:async next=>{const n=next.transactions.find(x=>x.id===txId);n.attachmentIds=[...(n.attachmentIds||[]),id];n.updatedAt=nowIso();}});}catch(err){await deleteAttachment(id);throw err;}toast('Attachment saved',record.encrypted?'Stored encrypted on this device.':'Stored locally on this device.');await openAttachmentsModal(txId);}catch(err){toast('Attachment failed',err.message||'Could not store the file.');}}
async function downloadAttachment(id){try{const a=await getAttachment(id);if(!a)return;const bytes=a.encrypted?await decryptAttachmentBytes(a,dek):Uint8Array.from(atob(a.data||''),c=>c.charCodeAt(0)).buffer;const blob=new Blob([bytes],{type:a.type||'application/octet-stream'});dl(blob,a.name||'ledgerly-attachment');}catch(err){toast('Cannot open attachment',err.message||'Unlock the ledger first.');}}
async function removeAttachment(id){const a=await getAttachment(id);if(!a)return;authorizeProtected(`Remove attachment ${a.name}`,async()=>{await commit({event:'Attachment removed',entityType:'attachment',entityId:id,creditorId:a.creditorId,details:a.name,snapshotReason:'Before attachment removal',mutate:async next=>{const tx=next.transactions.find(x=>x.id===a.transactionId);if(tx)tx.attachmentIds=(tx.attachmentIds||[]).filter(x=>x!==id);}});await deleteAttachment(id);closeModal();toast('Attachment removed','The financial record itself was not changed.');});}

async function buildBackupObject(){
  const attachments=await exportAllAttachments();const totals=state?overallSummary(state):null;const backup={format:'ledgerly-backup',backupVersion:3,createdAt:nowIso(),appVersion:APP_VERSION,schemaVersion:state?.schemaVersion||record?.schemaVersion||SCHEMA_VERSION,revision:Number(record?.revision||0),encrypted:Boolean(record?.encrypted),record:deepClone(record),attachments,summary:totals?{creditors:state.creditors.length,transactions:state.transactions.length,remainingHalalas:totals.remaining}:null,checksum:null};backup.checksum=await checksumObject(backup);return backup;
}
async function exportBackup(){
  try{const backup=await buildBackupObject();const stamp=todayLocal();dl(jsonBlob(backup),`Ledgerly_Backup_${stamp}_v${APP_VERSION}.json`);backupMeta={at:nowIso(),revision:Number(record?.revision||0)};await setMeta('backup',backupMeta);render();toast('Backup verified & exported',`Revision ${record?.revision||0} · checksum ${backup.checksum.slice(0,10)}…`);}catch(err){toast('Backup failed',err.message||'Could not export the ledger.');}
}
async function emergencyBackup(){try{const attachments=await exportAllAttachments();const obj={format:'ledgerly-emergency-raw',createdAt:nowIso(),appVersion:APP_VERSION,record,attachments,checksum:null};obj.checksum=await checksumObject(obj);dl(jsonBlob(obj),`Ledgerly_EMERGENCY_${todayLocal()}.json`);toast('Emergency backup exported','Raw local record exported without modification.');}catch(err){toast('Emergency backup failed',err.message||'');}}

function openBackupModal(){const changes=backupMeta.revision==null?Number(record?.revision||0):Math.max(0,Number(record?.revision||0)-Number(backupMeta.revision||0));ui.modal={type:'backup'};openModal(modalFrame(t('backup'),'Verified, portable backups with restore preview.',`<div class="backup-summary"><div><small>${t('lastBackup')}</small><strong>${backupMeta.at?shortDateTime(backupMeta.at):t('never')}</strong></div><div><small>${t('revision')}</small><strong>${record?.revision||0}</strong></div><div><small>${t('changesSinceBackup')}</small><strong>${changes}</strong></div><div><small>Protection</small><strong>${record?.encrypted?'Encrypted':'Not encrypted'}</strong></div></div><div class="settings-sections"><button class="btn btn-primary" data-action="export-backup" type="button">${t('exportBackup')}</button><button class="btn btn-soft" data-action="test-backup" type="button">${t('testBackup')}</button><button class="btn btn-soft" data-action="restore-backup" type="button">${t('restoreBackup')}</button><button class="btn btn-soft" data-action="merge-backup" type="button">Merge backup</button><button class="btn btn-soft" data-action="export-csv" type="button">${t('exportCsv')}</button><button class="btn btn-soft" data-action="export-ics" type="button">Export due dates (.ics)</button></div>`));}

async function parseBackupFile(file,mode){
  try{const obj=JSON.parse(await file.text());if(!['ledgerly-backup','ledgerly-emergency-raw'].includes(obj.format))throw new Error('This is not a Ledgerly backup.');const checksum=await checksumObject(obj);if(obj.checksum&&checksum!==obj.checksum)throw new Error('Backup checksum does not match. The file may be damaged.');if(obj.format==='ledgerly-emergency-raw')return showBackupPreview({obj,state:null,dek:null,mode,emergency:true});
    if(obj.encrypted){ui.modal={type:'backupPassword',obj,mode};openModal(modalFrame('Encrypted backup','Enter the password used by this backup to verify its contents.',`<form id="backupPasswordForm">${field(t('password'),`<input name="password" type="password" autocomplete="current-password" required>`,true)}<div id="backupPasswordError" class="form-error"></div><div class="form-actions"><button class="btn btn-soft" data-action="close-modal" type="button">${t('cancel')}</button><button class="btn btn-primary" type="submit">Verify backup</button></div></form>`));}
    else{const imported=reconcileState(obj.record?.payload);validateState(imported);showBackupPreview({obj,state:imported,dek:null,mode});}
  }catch(err){toast('Backup rejected',err.message||'The backup could not be read.');}
}
async function submitBackupPassword(form){const password=new FormData(form).get('password');const {obj,mode}=ui.modal;try{const bdek=await unlockSecurity(obj.record.security,password);const imported=reconcileState(await decryptJson(obj.record.envelope,bdek));validateState(imported);showBackupPreview({obj,state:imported,dek:bdek,mode});}catch(err){$('backupPasswordError').textContent='Password or encrypted backup is invalid.';}}
function analyzeMerge(imported){
  const creditorMap=new Map();const newCreditors=[];const conflicts=[];let duplicateCreditors=0;
  for(const c of imported.creditors){const existing=state.creditors.find(x=>x.id===c.id)||state.creditors.find(x=>normalizeName(x.name)===normalizeName(c.name));if(existing){creditorMap.set(c.id,existing.id);duplicateCreditors++;}else{creditorMap.set(c.id,c.id);newCreditors.push(deepClone(c));}}
  const txMap=new Map();const newTransactions=[];let duplicateTransactions=0;
  const currentTx=state.transactions;
  const importedSorted=[...imported.transactions].sort((a,b)=>Number(a.type!=='debt')-Number(b.type!=='debt'));
  for(const tx of importedSorted){const mappedCreditor=creditorMap.get(tx.creditorId)||tx.creditorId;const sameId=currentTx.find(x=>x.id===tx.id);const sem=currentTx.find(x=>x.creditorId===mappedCreditor&&x.type===tx.type&&Number(x.amountHalalas)===Number(tx.amountHalalas)&&x.effectiveDate===tx.effectiveDate&&String(x.description||'')===String(tx.description||''));if(sameId){const same=sameId.creditorId===mappedCreditor&&sameId.type===tx.type&&Number(sameId.amountHalalas)===Number(tx.amountHalalas)&&sameId.effectiveDate===tx.effectiveDate;if(!same){conflicts.push(`Transaction ID ${tx.id} exists with different financial content.`);continue;}txMap.set(tx.id,sameId.id);duplicateTransactions++;continue;}if(sem){txMap.set(tx.id,sem.id);duplicateTransactions++;continue;}const clone=deepClone(tx);clone.creditorId=mappedCreditor;newTransactions.push(clone);txMap.set(tx.id,clone.id);}
  for(const tx of newTransactions){tx.allocations=(tx.allocations||[]).map(a=>({...a,debtId:txMap.get(a.debtId)||a.debtId}));if(tx.reversedTransactionId)tx.reversedTransactionId=txMap.get(tx.reversedTransactionId)||tx.reversedTransactionId;}
  const combined=deepClone(state);combined.creditors.push(...newCreditors);combined.transactions.push(...newTransactions);const health=diagnostics(combined);if(!health.ok)conflicts.push(...health.issues.map(i=>i.message));
  return {creditorMap,txMap,newCreditors,newTransactions,duplicateCreditors,duplicateTransactions,conflicts};
}
function showBackupPreview(ctx){
  const s=ctx.state?overallSummary(ctx.state):null;if(ctx.mode==='merge'&&ctx.state&&!ctx.emergency)ctx.mergePlan=analyzeMerge(ctx.state);ui.modal={type:'backupPreview',ctx};
  const merge=ctx.mergePlan;const action=ctx.mode==='restore'?`<button class="btn btn-danger" data-action="apply-restore">Replace current ledger</button>`:ctx.mode==='merge'&&merge&&!merge.conflicts.length?`<button class="btn btn-primary" data-action="apply-merge-backup">Merge verified records</button>`:'';
  const mergeBox=merge?`<div class="backup-summary"><div><small>New creditors</small><strong>${merge.newCreditors.length}</strong></div><div><small>Matched creditors</small><strong>${merge.duplicateCreditors}</strong></div><div><small>New transactions</small><strong>${merge.newTransactions.length}</strong></div><div><small>Duplicate transactions</small><strong>${merge.duplicateTransactions}</strong></div></div>${merge.conflicts.length?`<div class="danger-box"><strong>Merge blocked by ${merge.conflicts.length} conflict(s).</strong><br>${merge.conflicts.slice(0,8).map(esc).join('<br>')}</div>`:'<div class="success-box">No financial conflicts detected. Existing records will not be duplicated.</div>'}`:'';
  openModal(modalFrame(ctx.mode==='restore'?'Restore preview':ctx.mode==='merge'?'Merge preview':'Backup test',ctx.emergency?'Emergency raw backup':`Checksum verified · ${shortDateTime(ctx.obj.createdAt)}`,ctx.emergency?`<div class="notice">This emergency backup contains a raw storage record. It is intended for recovery assistance, not direct replacement from the normal restore flow.</div><div class="success-box">Checksum verified successfully.</div>`:`<div class="success-box">Backup verified successfully. Ledger data was opened in memory without touching current data.</div><div class="backup-summary"><div><small>Creditors</small><strong>${ctx.state.creditors.length}</strong></div><div><small>Transactions</small><strong>${ctx.state.transactions.length}</strong></div><div><small>${t('remaining')}</small><strong>${rawMoney(s.remaining)}</strong></div><div><small>Schema / app</small><strong>${ctx.obj.schemaVersion} / ${esc(ctx.obj.appVersion)}</strong></div></div>${mergeBox}<div class="form-actions"><button class="btn btn-soft" data-action="close-modal">${t('close')}</button>${action}</div>`),{wide:true});
}
async function applyMergeBackup(){
  const ctx=ui.modal?.ctx;const plan=ctx?.mergePlan;if(!ctx?.state||!plan||plan.conflicts.length)return;
  const run=async()=>{
    const existingAttachments=await exportAllAttachments();const existingAttIds=new Set(existingAttachments.map(a=>a.id));const attachmentIdMap=new Map();const incomingAtts=[];const neededAttIds=new Set(plan.newTransactions.flatMap(tx=>tx.attachmentIds||[]));
    for(const a of (ctx.obj.attachments||[]).filter(x=>neededAttIds.has(x.id))){let newId=a.id;if(existingAttIds.has(newId))newId=uid('att');attachmentIdMap.set(a.id,newId);let bytes;if(a.encrypted){if(!ctx.dek)continue;bytes=new Uint8Array(await decryptAttachmentBytes(a,ctx.dek));}else bytes=Uint8Array.from(atob(a.data||''),c=>c.charCodeAt(0));const meta={...a,id:newId,data:null,iv:null,encrypted:false,updatedAt:nowIso()};incomingAtts.push(record.encrypted?await encryptAttachmentRecord(meta,bytes,dek):plainAttachmentRecord(meta,bytes));}
    const txs=deepClone(plan.newTransactions);for(const tx of txs)tx.attachmentIds=(tx.attachmentIds||[]).map(id=>attachmentIdMap.get(id)||id);
    await commit({event:'Backup merged',entityType:'system',details:`${plan.newCreditors.length} creditors / ${txs.length} transactions added`,reason:'Verified backup merge',snapshotReason:'Before backup merge',mutate:async next=>{
      next.creditors.push(...deepClone(plan.newCreditors));next.transactions.push(...txs);
      const ids=new Set((next.audit||[]).map(a=>a.id));for(const a of [...(ctx.state.auditArchive||[]),...(ctx.state.audit||[])])if(!ids.has(a.id))next.auditArchive.push(deepClone(a));
      const closeKeys=new Set(next.monthClosures.map(x=>x.month));for(const c of ctx.state.monthClosures||[])if(!closeKeys.has(c.month))next.monthClosures.push(deepClone(c));
      const templateKeys=new Set(next.templates.map(x=>x.id));for(const tp of ctx.state.templates||[])if(!templateKeys.has(tp.id))next.templates.push(deepClone(tp));
    }});
    for(const a of incomingAtts)await putAttachment(a);closeModal();toast('Backup merged',`${plan.newTransactions.length} new transaction(s) added without replacing current records.`);
  };authorizeProtected('Merge records from a verified backup',run);
}

async function applyRestore(){const ctx=ui.modal?.ctx;if(!ctx?.state)return;const run=async()=>{const expected=Number(record?.revision||0);await createManualSnapshot(record,'Pre-restore rollback snapshot');const imported=reconcileState(deepClone(ctx.state));imported.meta.revision=expected+1;imported.meta.updatedAt=nowIso();imported.meta.appVersion=APP_VERSION;await appendAudit(imported,{event:'Backup restored',details:`Restored backup from ${ctx.obj.createdAt}`,reason:'Explicit user restore'});let nextRecord;if(ctx.obj.encrypted){const envelope=await encryptJson(imported,ctx.dek);nextRecord={id:'current',encrypted:true,revision:expected+1,envelope,security:ctx.obj.record.security};}else nextRecord={id:'current',encrypted:false,revision:expected+1,payload:imported,security:null};const saved=await saveStateRecord(nextRecord,{expectedRevision:expected,snapshotReason:'Before restore'});await replaceAllAttachments(ctx.obj.attachments||[]);record=saved;state=imported;security=saved.security||null;dek=ctx.obj.encrypted?ctx.dek:null;localStorage.setItem(INSTALL_MARKER,nowIso());leaveSafeMode();backupMeta={at:null,revision:null};await setMeta('backup',backupMeta);closeModal();render();toast('Restore complete','Current data was replaced only after validation and a rollback snapshot was created.');};authorizeProtected('Replace the current ledger from a verified backup',run);}

function exportCsv(){try{dl(new Blob([humanCsv(state)],{type:'text/csv;charset=utf-8'}),`Ledgerly_Export_${todayLocal()}.csv`);toast('CSV exported','Human-readable transaction export created.');}catch(err){toast('CSV failed',err.message||'');}}
function exportIcs(){const debts=state.transactions.filter(tx=>tx.type==='debt'&&!tx.voidedAt&&tx.dueDate&&debtRemaining(state,tx.id)>0);const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Ledgerly//Debt Due Dates//EN'];for(const tx of debts){const c=creditorById(tx.creditorId);const date=tx.dueDate.replace(/-/g,'');lines.push('BEGIN:VEVENT',`UID:${tx.id}@ledgerly.local`,`DTSTART;VALUE=DATE:${date}`,`SUMMARY:${String(`Ledgerly: ${c?.name||'Debt'} due`).replace(/[,;]/g,' ')}`,`DESCRIPTION:${String(`${rawMoney(debtRemaining(state,tx.id))} remaining`).replace(/[,;]/g,' ')}`,'END:VEVENT');}lines.push('END:VCALENDAR');dl(new Blob([lines.join('\r\n')],{type:'text/calendar'}),`Ledgerly_Due_Dates_${todayLocal()}.ics`);toast('Calendar exported',`${debts.length} due date(s) included.`);}

function reportHtml({redacted=false}={}){const o=overallSummary(state);const rows=o.summaries.sort((a,b)=>b.remaining-a.remaining).map(s=>`<tr><td>${redacted?'Creditor':esc(s.creditor.name)}</td><td>${redacted?'••••':rawMoney(s.liability)}</td><td>${redacted?'••••':rawMoney(s.reductions)}</td><td>${redacted?'••••':rawMoney(s.remaining)}</td><td>${esc(s.status)}</td></tr>`).join('');return `<!doctype html><meta charset="utf-8"><title>Ledgerly Personal Report</title><style>body{font:14px system-ui;margin:40px;color:#17211e}h1{font-size:30px}.meta{color:#78847f}.cards{display:flex;gap:12px;margin:25px 0}.card{border:1px solid #ddd;border-radius:12px;padding:15px;min-width:150px}.card small{display:block;color:#777}.card b{font-size:19px}table{border-collapse:collapse;width:100%}th,td{text-align:left;padding:10px;border-bottom:1px solid #ddd}th{font-size:11px;text-transform:uppercase;color:#777}@media print{body{margin:15mm}}</style><h1>Ledgerly · Personal Debt Report</h1><div class="meta">Generated ${esc(shortDateTime(nowIso()))} · App v${APP_VERSION} · Revision ${state.meta.revision}</div><div class="cards"><div class="card"><small>Liability</small><b>${redacted?'••••':rawMoney(o.liability)}</b></div><div class="card"><small>Paid / settled</small><b>${redacted?'••••':rawMoney(o.reductions)}</b></div><div class="card"><small>Remaining</small><b>${redacted?'••••':rawMoney(o.remaining)}</b></div></div><table><thead><tr><th>Creditor</th><th>Original</th><th>Paid</th><th>Remaining</th><th>Status</th></tr></thead><tbody>${rows}</tbody></table><p class="meta">Actual ledger records only. Planned payments are not treated as actual payments.</p>`;}
function exportReport(redacted=false){dl(new Blob([reportHtml({redacted})],{type:'text/html'}),`Ledgerly_Report_${redacted?'Redacted_':''}${todayLocal()}.html`);toast('Report exported',redacted?'Names and amounts were redacted.':'Full personal report exported.');}

function openAsOfModal(){ui.modal={type:'asOf'};openModal(modalFrame(t('asOf'),'View the ledger at a historical calendar date without changing current data.',`<form id="asOfForm">${field(t('asOf'),`<input name="date" type="date" value="${todayLocal()}" max="${todayLocal()}" required>`,true)}<div class="form-actions"><button class="btn btn-primary" type="submit">Calculate</button></div></form><div id="asOfResult"></div>`));}
function calculateAsOf(form){const date=new FormData(form).get('date');const o=overallSummary(state,date);$('asOfResult').innerHTML=`<div class="backup-summary"><div><small>Liability</small><strong>${rawMoney(o.liability)}</strong></div><div><small>Paid / settled</small><strong>${rawMoney(o.reductions)}</strong></div><div><small>Remaining</small><strong>${rawMoney(o.remaining)}</strong></div><div><small>Active creditors</small><strong>${o.active}</strong></div></div>`;}

function closeCurrentMonth(){const month=todayLocal().slice(0,7);if(state.monthClosures.some(x=>x.month===month))return toast('Month already closed','A read-only snapshot for this month already exists.');confirmModal({title:t('monthlyClose'),text:`Create a read-only snapshot for ${month}? This does not lock or freeze future entries.`,confirm:'Create snapshot',onConfirm:async()=>{const o=overallSummary(state);await commit({event:'Monthly snapshot created',entityType:'month-close',details:month,snapshotReason:'Before monthly close',mutate:async next=>{next.monthClosures.push({id:uid('close'),month,createdAt:nowIso(),revision:next.meta.revision,totals:{liability:o.liability,reductions:o.reductions,remaining:o.remaining,active:o.active}});next.meta.lastMonthlyClose=month;}});closeModal();toast('Monthly snapshot saved',`${month} · ${rawMoney(o.remaining)} remaining.`);}});}

