async function saveSettingsFromModal(){const theme=$('settingsTheme')?.value||state.settings.theme;const privacy=$('settingsPrivacy')?.value||state.settings.privacyLevel;const language='en';const autoLock=Number($('settingsAutoLock')?.value||15);const bg=Boolean($('settingsBgLock')?.checked);const motion=Boolean($('settingsMotion')?.checked);const autoAllocation=$('settingsAllocation')?.value||state.settings.autoAllocation;const duplicateWarnings=Boolean($('settingsDuplicates')?.checked);await commit({event:'Settings updated',details:'Appearance, privacy, planning and lock preferences',mutate:async s=>{Object.assign(s.settings,{theme,privacyLevel:privacy,language,autoLockMinutes:autoLock,lockOnBackground:bg,reduceMotion:motion,autoAllocation,duplicateWarnings});}});closeModal();toast('Settings saved','Preferences are stored with this ledger.');}

function openSecurityEnable(){ui.modal={type:'enableSecurity'};openModal(modalFrame(t('protect'),'Encrypt this ledger and future attachments on this device.',`<div class="notice">Ledgerly uses AES-GCM with a password-derived key. If you forget the password, the recovery key is the only alternative.</div><form id="enableSecurityForm"><div class="form-grid">${field(t('password'),`<input name="password" type="password" minlength="8" autocomplete="new-password" required>`)}${field('Confirm password',`<input name="confirm" type="password" minlength="8" autocomplete="new-password" required>`)}<label class="field full"><span><input name="recovery" type="checkbox" checked> Create an offline recovery key</span></label></div><div class="form-actions"><button class="btn btn-soft" data-action="close-modal" type="button">${t('cancel')}</button><button class="btn btn-primary" type="submit">Encrypt ledger</button></div></form>`));}
async function enableSecuritySubmit(form){const d=Object.fromEntries(new FormData(form).entries());if(String(d.password).length<8)return toast('Password too short','Use at least 8 characters.');if(d.password!==d.confirm)return toast('Passwords differ','Enter the same password twice.');try{const created=await createSecurity(d.password,{withRecovery:d.recovery==='on',autoLockMinutes:state.settings.autoLockMinutes,lockOnBackground:state.settings.lockOnBackground});const expected=Number(record.revision);const next=deepClone(state);next.meta.revision=expected+1;next.meta.updatedAt=nowIso();await appendAudit(next,{event:'Ledger protection enabled',details:'Migrated to AES-GCM security envelope',reason:'User enabled protection'});const existingAttachments=await exportAllAttachments();const securedAttachments=[];for(const a of existingAttachments){let bytes;if(a.encrypted){if(!dek)throw new Error('Existing encrypted attachment key is unavailable.');bytes=new Uint8Array(await decryptAttachmentBytes(a,dek));}else bytes=Uint8Array.from(atob(a.data||''),c=>c.charCodeAt(0));securedAttachments.push(await encryptAttachmentRecord({...a,encrypted:false,data:null,iv:null},bytes,created.dek));}const envelope=await encryptJson(next,created.dek);const saved=await saveStateRecord({id:'current',encrypted:true,revision:expected+1,envelope,security:created.security},{expectedRevision:expected,snapshotReason:null});await replaceAllAttachments(securedAttachments);record=saved;state=next;security=created.security;dek=created.dek;await clearSnapshots();await clearDrafts();cleanupLegacyKeys();await clearLegacyDatabase();closeModal();render();toast('Ledger encrypted','Plaintext legacy storage, snapshots and attachments were migrated to encrypted storage.');if(created.recoveryKey)showRecoveryKey(created.recoveryKey);}catch(err){toast('Protection failed',err.message||'Could not encrypt the ledger.');}}
function showRecoveryKey(key){ui.modal={type:'recoveryKey'};openModal(modalFrame(t('recoveryKey'),'Save this outside your phone before closing.',`<div class="danger-box">${t('recoveryWarning')}</div><div class="recovery-code">${esc(recoveryDisplay(key))}</div><div class="form-actions"><button class="btn btn-soft" data-action="copy-recovery" data-key="${attr(key)}">Copy</button><button class="btn btn-primary" data-action="close-modal">${t('recoverySaved')}</button></div>`));}
function openChangePassword(){ui.modal={type:'changePassword'};openModal(modalFrame(t('changePassword'),'The data encryption key stays the same; only the password wrapping it changes.',`<form id="changePasswordForm"><div class="form-grid">${field('Current password',`<input name="old" type="password" autocomplete="current-password" required>`)}${field('New password',`<input name="new" type="password" minlength="8" autocomplete="new-password" required>`)}${field('Confirm new password',`<input name="confirm" type="password" minlength="8" autocomplete="new-password" required>`,true)}</div><div id="changePasswordError" class="form-error"></div><div class="form-actions"><button class="btn btn-soft" data-action="close-modal">${t('cancel')}</button><button class="btn btn-primary" type="submit">Change password</button></div></form>`));}
async function changePasswordSubmit(form){const d=Object.fromEntries(new FormData(form).entries());if(d.new!==d.confirm||String(d.new).length<8)return $('changePasswordError').textContent='New passwords do not match or are too short.';try{await unlockSecurity(security,d.old);const nextSecurity=await changePassword(security,dek,d.new);const expected=Number(record.revision);const next=deepClone(state);next.meta.revision=expected+1;next.meta.updatedAt=nowIso();await appendAudit(next,{event:'Master password changed',details:'Encryption key re-wrapped',reason:'User password change'});const envelope=await encryptJson(next,dek);const saved=await saveStateRecord({id:'current',encrypted:true,revision:expected+1,envelope,security:nextSecurity},{expectedRevision:expected,snapshotReason:'Before password change'});security=nextSecurity;record=saved;state=next;closeModal();render();toast('Password changed','Recovery key remains valid unless you rotate security later.');}catch{$('changePasswordError').textContent='Current password was not accepted.';}}

async function verifyAuditChain(){const entries=state.audit||[];let verified=0,legacy=0,broken=0;for(let i=0;i<entries.length;i++){const e=entries[i];if(!e.hash){legacy++;continue;}const expected=await sha256Text(JSON.stringify({...e,hash:null}));const link=i<entries.length-1?(entries[i+1].hash||''):((state.auditArchive||[])[0]?.hash||'');if(expected!==e.hash||e.prevHash!==link)broken++;else verified++;}return {verified,legacy,broken};}
async function openDiagnosticsModal(){storageInfo=await storageEstimate();const d=diagnostics(state);const chain=await verifyAuditChain();const pending=await pendingOperations();const attachments=await exportAllAttachments();const referenced=new Set(state.transactions.flatMap(tx=>tx.attachmentIds||[]));const orphanAttachments=attachments.filter(a=>!referenced.has(a.id));ui.modal={type:'diagnostics',orphanAttachments};const issues=d.issues.map(i=>`<div class="tx-row"><div class="tx-title">${esc(i.code)}</div><div class="tx-meta">${esc(i.message)}</div></div>`).join('');const used=storageInfo.usage?`${(storageInfo.usage/1024/1024).toFixed(2)} MB`:'Unknown';const quota=storageInfo.quota?`${(storageInfo.quota/1024/1024).toFixed(0)} MB`:'Unknown';openModal(modalFrame(t('diagnostics'),'Read-only health report. No financial amount is repaired automatically.',`<div class="diagnostic-grid"><div class="diagnostic-item"><small>App / schema</small><strong>${APP_VERSION} / ${SCHEMA_VERSION}</strong></div><div class="diagnostic-item"><small>Build ID</small><strong>${BUILD_ID}</strong></div><div class="diagnostic-item"><small>Revision</small><strong>${record.revision}</strong></div><div class="diagnostic-item"><small>Data health</small><strong>${d.ok?'✓ Reconciled':`${d.issues.length} issue(s)`}</strong></div><div class="diagnostic-item"><small>Audit chain</small><strong>${chain.broken?'⚠ '+chain.broken+' broken':`✓ ${chain.verified} verified`} · ${chain.legacy} legacy</strong></div><div class="diagnostic-item"><small>Storage</small><strong>${used} / ${quota}</strong></div><div class="diagnostic-item"><small>Persistence</small><strong>${storageInfo.persisted?'Persistent':'Best effort'}</strong></div><div class="diagnostic-item"><small>Pending operations</small><strong>${pending.length}</strong></div><div class="diagnostic-item"><small>Orphan attachments</small><strong>${orphanAttachments.length}</strong></div></div>${issues?`<h3>Integrity issues</h3><div class="ledger-list">${issues}</div>`:'<div class="success-box">All financial records reconcile. No orphan transactions or overpayments were detected.</div>'}${orphanAttachments.length?`<div class="notice">Orphan attachment files can be cleaned safely because they are not referenced by any financial record.</div><button class="btn btn-soft" data-action="clean-orphan-attachments">Clean orphan attachments</button>`:''}<div class="form-actions"><button class="btn btn-soft" data-action="emergency-backup">${t('emergencyBackup')}</button><button class="btn btn-primary" data-action="close-modal">${t('close')}</button></div>`),{wide:true});}
async function cleanOrphanAttachments(){const items=ui.modal?.orphanAttachments||[];for(const a of items)await deleteAttachment(a.id);toast('Storage cleaned',`${items.length} orphan attachment(s) removed. No financial record was modified.`);openDiagnosticsModal();}

function openAuditModal(){const rows=(state.audit||[]).map(a=>`<div class="tx-row"><div class="tx-top"><div><div class="tx-title">${esc(a.event)}</div><div class="tx-meta">${shortDateTime(a.ts)} · ${esc(a.reason||a.details||'')}</div></div><span class="badge ${a.hash?'ok':'warn'}">${a.hash?'Hashed':'Legacy'}</span></div>${a.hash?`<div class="audit-hash">${esc(a.hash)}</div>`:''}</div>`).join('');ui.modal={type:'audit'};openModal(modalFrame('Audit trail',`New entries are hash-linked. ${(state.auditArchive||[]).length} older entries are preserved in the archive and backups.`,`<div class="ledger-list">${rows||'<div class="tx-meta">No audit entries.</div>'}</div>`),{wide:true});}

async function openSnapshotsModal(){const snaps=await listSnapshots(20);ui.modal={type:'snapshots'};openModal(modalFrame('Rollback snapshots','App/data rollback is separate from code updates.',`<div class="notice">Snapshots are created before sensitive writes. Restoring one replaces ledger data but does not change the installed app version.</div><div class="ledger-list">${snaps.map(s=>`<div class="tx-row"><div class="tx-top"><div><div class="tx-title">Revision ${s.revision}</div><div class="tx-meta">${shortDateTime(s.createdAt)} · ${esc(s.reason||'Snapshot')}</div></div><button class="btn btn-small btn-soft" data-action="restore-snapshot" data-id="${attr(s.id)}">Restore</button></div></div>`).join('')||'<div class="tx-meta">No snapshots available.</div>'}</div>`));}
async function restoreSnapshot(id){const snap=await getSnapshot(id);if(!snap)return;const run=async()=>{try{let snapState,snapDek=dek,snapSecurity=security;if(snap.record.encrypted){if(!snapDek)throw new Error('Unlock the ledger first.');snapState=reconcileState(await decryptJson(snap.record.envelope,snapDek));}else snapState=reconcileState(snap.record.payload);validateState(snapState);const expected=Number(record.revision);await createManualSnapshot(record,'Pre-rollback snapshot');snapState.meta.revision=expected+1;await appendAudit(snapState,{event:'Snapshot restored',details:`Restored revision ${snap.revision}`,reason:'Explicit data rollback'});const nr=snap.record.encrypted?{id:'current',encrypted:true,revision:expected+1,envelope:await encryptJson(snapState,snapDek),security:snapSecurity}:{id:'current',encrypted:false,revision:expected+1,payload:snapState,security:null};record=await saveStateRecord(nr,{expectedRevision:expected,snapshotReason:'Before rollback'});state=snapState;closeModal();render();toast('Snapshot restored','The app version did not change.');}catch(err){toast('Rollback blocked',err.message||'This snapshot cannot be decrypted with the current key.');}};authorizeProtected(`Restore snapshot revision ${snap.revision}`,run);}

function openArchivedCreditors(){const list=state.creditors.filter(c=>c.archivedAt);ui.modal={type:'archived'};openModal(modalFrame('Archived creditors','Historical creditors hidden from the active money map.',`<div class="ledger-list">${list.map(c=>{const s=creditorSummary(state,c.id);return `<div class="tx-row"><div class="tx-top"><div><div class="tx-title">${esc(c.name)}</div><div class="tx-meta">Archived ${shortDateTime(c.archivedAt)} · ${rawMoney(s.remaining)} remaining</div></div><button class="btn btn-small btn-soft" data-action="restore-creditor" data-id="${attr(c.id)}">Restore</button></div></div>`;}).join('')||'<div class="tx-meta">No archived creditors.</div>'}</div>`));}
async function restoreCreditor(id){await commit({event:'Creditor restored',entityType:'creditor',entityId:id,creditorId:id,details:creditorById(id)?.name,snapshotReason:'Before creditor restore',mutate:async next=>{const c=next.creditors.find(x=>x.id===id);c.archivedAt=null;c.updatedAt=nowIso();}});openArchivedCreditors();toast('Creditor restored','Returned to the active money map.');}

function newEmptyLedger(){confirmModal({title:'Start a new empty ledger?',text:'This creates a rollback snapshot first, then replaces all active ledger records. This is not the old “reset to seed data” behavior.',confirm:'Continue',danger:true,onConfirm:()=>authorizeProtected('Replace the ledger with a new empty ledger',async()=>{const expected=Number(record.revision);await createManualSnapshot(record,'Before new empty ledger');const fresh=newEmptyState();fresh.meta.revision=expected+1;await appendAudit(fresh,{event:'New empty ledger started',details:'Previous ledger preserved in rollback snapshot',reason:'Explicit danger-zone action'});let nr;if(record.encrypted){nr={id:'current',encrypted:true,revision:expected+1,envelope:await encryptJson(fresh,dek),security};}else nr={id:'current',encrypted:false,revision:expected+1,payload:fresh,security:null};record=await saveStateRecord(nr,{expectedRevision:expected,snapshotReason:'Before new empty ledger'});state=fresh;closeModal();render();toast('New ledger ready','Previous data is preserved in a rollback snapshot.');})});}

function openExplainTotals(){const rows=explainTotals(state);ui.modal={type:'explain'};openModal(modalFrame(t('explainTotal'),'Every dashboard total comes from this same ledger engine.',`<div class="explain-table"><div class="explain-row header"><span>Creditor</span><span>Liability</span><span>Paid / settled</span><span>Remaining</span></div>${rows.map(r=>`<div class="explain-row"><strong class="creditor-name">${esc(r.name)}</strong><span class="sensitive">${money(r.liability)}</span><span class="sensitive">${money(r.reductions)}</span><strong class="sensitive">${money(r.remaining)}</strong></div>`).join('')}</div>`),{wide:true});}
function openReportMenu(){ui.modal={type:'reportMenu'};openModal(modalFrame(t('report'),'Export a human-readable report independent of the Ledgerly backup format.',`<div class="settings-sections"><button class="btn btn-primary" data-action="export-report-full">Full report</button><button class="btn btn-soft" data-action="export-report-redacted">${t('redacted')}</button><button class="btn btn-soft" data-action="export-csv">${t('exportCsv')}</button><button class="btn btn-soft" data-action="export-ics">Export due dates (.ics)</button></div>`));}

function setupStaticEvents(){
  ['heroAddDebtBtn','addDebtBtn','mobileAddDebtBtn','emptyAddDebtBtn'].forEach(id=>$(id)?.addEventListener('click',()=>openAddDebtModal()));
  $('settingsBtn').addEventListener('click',openSettingsModal);$('themeBtn').addEventListener('click',cycleTheme);$('privacyBtn').addEventListener('click',cyclePrivacy);
  $('toggleInsightsBtn').addEventListener('click',()=>{ui.insights=!ui.insights;render();});$('balanceCard').addEventListener('click',openExplainTotals);$('explainTotalBtn').addEventListener('click',openExplainTotals);
  $('searchInput').addEventListener('input',e=>{ui.search=e.target.value;renderCreditors();});$('sortSelect').addEventListener('change',e=>{ui.sort=e.target.value;renderCreditors();});$('filterBtn').addEventListener('click',()=>$('filterChips').scrollIntoView({behavior:'smooth',block:'center'}));
  $('asOfBtn').addEventListener('click',openAsOfModal);$('closeMonthBtn').addEventListener('click',closeCurrentMonth);$('auditBtn').addEventListener('click',openAuditModal);
  $('safeRestoreBtn').addEventListener('click',()=>{ui.fileMode='restore';$('restoreFileInput').click();});
  $('reloadUpdateBtn').addEventListener('click',()=>{if(swRegistration?.waiting)swRegistration.waiting.postMessage({type:'SKIP_WAITING'});else location.reload();});$('safeBackupBtn').addEventListener('click',emergencyBackup);$('safeDiagnosticsBtn').addEventListener('click',()=>{if(state)openDiagnosticsModal();else emergencyBackup();});
  $('unlockForm').addEventListener('submit',async e=>{e.preventDefault();const secret=$('unlockPassword').value;try{await unlockCurrent(secret,{recovery:ui.unlockRecovery===true});$('unlockPassword').value='';}catch{}});
  $('useRecoveryBtn').addEventListener('click',()=>{ui.unlockRecovery=!ui.unlockRecovery;const input=$('unlockPassword');input.value='';input.type=ui.unlockRecovery?'text':'password';input.placeholder=ui.unlockRecovery?'LDG-…':'Master password';$('useRecoveryBtn').textContent=ui.unlockRecovery?'Use master password instead':'Use recovery key instead';$('unlockError').textContent=ui.unlockRecovery?'Enter the offline recovery key exactly as saved.':'';input.focus();});
  $('restoreFileInput').addEventListener('change',async e=>{const file=e.target.files?.[0];e.target.value='';if(file)await parseBackupFile(file,ui.fileMode||'test');});
  $('attachmentFileInput').addEventListener('change',async e=>{const file=e.target.files?.[0];e.target.value='';if(file)await handleAttachmentFile(file);});
  $('modalBackdrop').addEventListener('click',e=>{if(e.target===$('modalBackdrop'))closeModal();});
  document.addEventListener('click',handleDelegatedClick);
  document.addEventListener('submit',handleDelegatedSubmit);
  document.addEventListener('input',handleDraftInput);
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('modalBackdrop').hidden)closeModal();armAutoLock();},{passive:true});
  ['pointerdown','touchstart'].forEach(ev=>document.addEventListener(ev,armAutoLock,{passive:true}));
  window.addEventListener('online',updateConnectivity);window.addEventListener('offline',updateConnectivity);
  document.addEventListener('visibilitychange',()=>{clearTimeout(backgroundTimer);if(document.hidden&&record?.encrypted&&(state?.settings?.lockOnBackground??true)){backgroundTimer=setTimeout(()=>{if(document.hidden)lockApp();},20000);}else armAutoLock();});
  matchMedia('(prefers-color-scheme:dark)').addEventListener?.('change',()=>{if(state?.settings?.theme==='system')applyTheme();});
  window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstallPrompt=e;});
  window.addEventListener('popstate',()=>{if(!$('modalBackdrop').hidden)closeModal(true);});
  revisionChannel(async msg=>{if(msg?.type==='revision'&&Number(msg.revision)>Number(record?.revision||0)&&Date.now()-lastWriteAt>800){await reloadFromStorage();toast('Ledger updated in another tab',`Loaded revision ${msg.revision}.`);}});
}

async function handleDelegatedClick(e){
  const filter=e.target.closest('[data-filter]');if(filter){ui.filter=filter.dataset.filter;renderFilters();renderCreditors();return;}
  const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;
  try{
    if(a==='confirm-async-yes'){const r=ui.modal?.resolve;closeModal();return r?.(true);}
    if(a==='confirm-async-no'){const r=ui.modal?.resolve;closeModal();return r?.(false);}
    if(a==='close-modal'){const r=ui.modal?.type==='confirmAsync'?ui.modal.resolve:null;await clearCurrentDraft();closeModal();return r?.(false);}
    if(a==='confirm-modal'){const cb=ui.modal?.onConfirm;return cb?.();}
    if(a==='toggle-creditor'){ui.expanded.has(id)?ui.expanded.delete(id):ui.expanded.add(id);return renderCreditors();}
    if(a==='copy-creditor')return copyCreditorSummary(id);
    if(a==='add-payment')return openPaymentModal(id);
    if(a==='add-debt-creditor')return openAddDebtModal(id);
    if(a==='add-adjustment')return openAdjustmentModal(id);
    if(a==='add-waiver')return openWaiverModal(id);
    if(a==='plan')return openPlanModal(id);
    if(a==='creditor-menu')return openCreditorMenu(id);
    if(a==='edit-tx')return openEditTx(id);
    if(a==='void-tx')return openVoidTx(id);
    if(a==='reverse-tx')return openReverseTx(id);
    if(a==='move-tx')return openMoveTx(id);
    if(a==='attachments')return openAttachmentsModal(id);
    if(a==='creditor-details')return openCreditorDetails(id);
    if(a==='rename-creditor')return openRenameCreditor(id);
    if(a==='statement')return openStatement(id);
    if(a==='merge-creditor')return openMergeCreditor(id);
    if(a==='templates-creditor')return openTemplatesModal(id);
    if(a==='archive-creditor')return archiveCreditor(id);
    if(a==='statement-redact')return openStatement(id,{redacted:!document.querySelector('.statement-total')?.textContent.includes('••••')});
    if(a==='print'){if(ui.privacy!=='none')return toast('Print privacy','Privacy mode is active. Export a redacted report instead.');return window.print();}
    if(a==='generate-template')return generateTemplate(id);
    if(a==='add-attachment'){ui.attachmentTarget=id;return $('attachmentFileInput').click();}
    if(a==='download-attachment')return downloadAttachment(id);
    if(a==='delete-attachment')return removeAttachment(id);
    if(a==='export-backup')return exportBackup();
    if(a==='test-backup'){ui.fileMode='test';return $('restoreFileInput').click();}
    if(a==='restore-backup'){ui.fileMode='restore';return $('restoreFileInput').click();}
    if(a==='merge-backup'){ui.fileMode='merge';return $('restoreFileInput').click();}
    if(a==='apply-restore')return applyRestore();
    if(a==='apply-merge-backup')return applyMergeBackup();
    if(a==='export-csv')return exportCsv();
    if(a==='export-ics')return exportIcs();
    if(a==='export-report-full')return exportReport(false);
    if(a==='export-report-redacted')return exportReport(true);
    if(a==='backup-menu')return openBackupModal();
    if(a==='report-menu')return openReportMenu();
    if(a==='templates')return openTemplatesModal();
    if(a==='archived-creditors')return openArchivedCreditors();
    if(a==='snapshots')return openSnapshotsModal();
    if(a==='diagnostics')return openDiagnosticsModal();
    if(a==='audit')return openAuditModal();
    if(a==='glossary')return openGlossary();
    if(a==='finish-onboarding')return finishOnboarding();
    if(a==='enable-security')return openSecurityEnable();
    if(a==='change-password')return openChangePassword();
    if(a==='lock-now'){closeModal();return lockApp();}
    if(a==='save-settings')return saveSettingsFromModal();
    if(a==='clean-orphan-attachments')return cleanOrphanAttachments();
    if(a==='emergency-backup')return emergencyBackup();
    if(a==='restore-snapshot')return restoreSnapshot(id);
    if(a==='restore-creditor')return restoreCreditor(id);
    if(a==='new-empty-ledger')return newEmptyLedger();
    if(a==='copy-recovery'){return navigator.clipboard?.writeText(b.dataset.key||'').then(()=>toast('Recovery key copied','Store it outside this device.'));}
  }catch(err){console.error(err);toast('Action failed',err.message||'Unexpected error.');}
}

async function handleDelegatedSubmit(e){
  const form=e.target;e.preventDefault();try{
    if(form.id==='debtForm')return await saveDebt(form);
    if(form.id==='paymentForm')return await savePayment(form);
    if(form.id==='adjustmentForm')return await saveAdjustment(form);
    if(form.id==='waiverForm')return await saveWaiver(form);
    if(form.id==='authorizeForm')return await submitAuthorization(form);
    if(form.id==='editTxForm')return await prepareEditTx(form);
    if(form.id==='voidTxForm')return await prepareVoid(form);
    if(form.id==='reverseTxForm')return await prepareReverse(form);
    if(form.id==='creditorDetailsForm')return await saveCreditorDetails(form);
    if(form.id==='renameCreditorForm')return await prepareRename(form);
    if(form.id==='mergeCreditorForm')return await prepareMerge(form);
    if(form.id==='moveTxForm')return await prepareMoveTx(form);
    if(form.id==='templateForm')return await saveTemplate(form);
    if(form.id==='backupPasswordForm')return await submitBackupPassword(form);
    if(form.id==='asOfForm')return calculateAsOf(form);
    if(form.id==='enableSecurityForm')return await enableSecuritySubmit(form);
    if(form.id==='changePasswordForm')return await changePasswordSubmit(form);
  }catch(err){console.error(err);toast('Save failed',err.message||'The operation could not be completed.');}
}

bootstrap().catch(err=>setSafeMode('Ledgerly could not start safely.',err));

function openCreditorDetails(id){const c=creditorById(id);ui.modal={type:'creditorDetails',creditorId:id};openModal(modalFrame('Creditor details',c.name,`<form id="creditorDetailsForm"><div class="form-grid">${field('Phone',`<input name="phone" value="${attr(c.contact?.phone||'')}" maxlength="40">`)}${field('Email',`<input name="email" type="email" value="${attr(c.contact?.email||'')}" maxlength="100">`)}${field('Tags (comma separated)',`<input name="tags" value="${attr((c.tags||[]).join(', '))}" maxlength="200">`,true)}${field(t('notes'),`<textarea name="notes" maxlength="1000">${esc(c.notes||'')}</textarea>`,true)}</div><div class="form-actions"><button class="btn btn-soft" data-action="close-modal">${t('cancel')}</button><button class="btn btn-primary" type="submit">${t('save')}</button></div></form>`));}
async function saveCreditorDetails(form){const data=Object.fromEntries(new FormData(form).entries());const id=ui.modal.creditorId;await commit({event:'Creditor details updated',entityType:'creditor',entityId:id,creditorId:id,details:'Contact details, tags or notes updated',snapshotReason:'Before creditor details update',mutate:async next=>{const c=next.creditors.find(x=>x.id===id);c.contact={phone:String(data.phone||'').trim(),email:String(data.email||'').trim()};c.tags=String(data.tags||'').split(',').map(x=>x.trim()).filter(Boolean).slice(0,20);c.notes=String(data.notes||'').trim();c.updatedAt=nowIso();}});closeModal();toast('Creditor details saved','Search now includes aliases, tags and contact details.');}

function openMoveTx(txId){const tx=txById(txId);if(!tx||tx.type==='reversal')return;const targets=state.creditors.filter(c=>!c.archivedAt&&c.id!==tx.creditorId);if(!targets.length)return toast('No target creditor','Add another creditor first.');if(tx.type==='debt'){const dependent=state.transactions.some(x=>!x.voidedAt&&(x.allocations||[]).some(a=>a.debtId===tx.id));if(dependent)return toast('Move blocked','This debt already has allocated payments or waivers. Move or correct those dependent records first.');}ui.modal={type:'moveTx',txId};openModal(modalFrame(t('moveRecord'),`${typeLabel(tx)} · ${creditorById(tx.creditorId)?.name}`,`<div class="notice">Moving a record changes its creditor identity without deleting or recreating the financial entry. The audit trail records the move.</div><form id="moveTxForm">${field('Move to',`<select name="targetId">${targets.map(c=>`<option value="${attr(c.id)}">${esc(c.name)}</option>`).join('')}</select>`,true)}${field(t('reason'),`<input name="reason" maxlength="160" required placeholder="Wrong creditor, duplicate identity…">`,true)}<div class="form-actions"><button class="btn btn-soft" data-action="close-modal">${t('cancel')}</button><button class="btn btn-primary" type="submit">Continue to authorization</button></div></form>`));}
async function prepareMoveTx(form){const data=Object.fromEntries(new FormData(form).entries());const tx=txById(ui.modal.txId);const targetId=data.targetId;const reason=String(data.reason||'').trim();if(!reason)return toast('Reason required','Explain why the record is moving.');const targetSummary=creditorSummary(state,targetId);if(['payment','waiver'].includes(tx.type)&&tx.amountHalalas>targetSummary.remaining)return toast('Move blocked',`Target creditor has only ${rawMoney(targetSummary.remaining)} remaining.`);if(tx.type==='adjustment'&&tx.adjustmentDirection==='decrease'&&tx.amountHalalas>targetSummary.remaining)return toast('Move blocked','The decrease would exceed the target balance.');authorizeProtected(`Move ${typeLabel(tx)} to ${creditorById(targetId)?.name}`,()=>applyMoveTx(tx.id,targetId,reason));}
async function applyMoveTx(txId,targetId,reason){const tx=txById(txId);const oldId=tx.creditorId;await commit({event:'Transaction moved',entityType:'transaction',entityId:txId,creditorId:targetId,reason,details:`Moved from ${creditorById(oldId)?.name} to ${creditorById(targetId)?.name}`,snapshotReason:'Before moving transaction',mutate:async next=>{const n=next.transactions.find(x=>x.id===txId);n.creditorId=targetId;n.updatedAt=nowIso();n.modifiedByVersion=APP_VERSION;if(['payment','waiver'].includes(n.type)){const temp={...next,transactions:next.transactions.filter(x=>x.id!==n.id)};const alloc=allocateReduction(temp,targetId,n.amountHalalas,next.settings.autoAllocation||'oldest-first');n.allocations=alloc.allocations;n.allocationMode='moved-auto';}}});const atts=await listAttachments({transactionId:txId});for(const a of atts)await putAttachment({...a,creditorId:targetId,updatedAt:nowIso()});closeModal();ui.expanded.add(targetId);toast('Record moved','The transaction ID and history stayed intact.');}

function maybeOnboard(){if(!state||state.settings.onboarded||state.creditors.length)return;ui.modal={type:'onboarding'};openModal(modalFrame('Welcome to Ledgerly','Three rules keep the ledger trustworthy.',`<div class="settings-sections"><div class="settings-card"><h3>1 · Your data is local-first</h3><p class="tx-meta">Ledgerly stores the active ledger on this device. Export verified backups regularly.</p></div><div class="settings-card"><h3>2 · Actual money stays separate from plans</h3><p class="tx-meta">A plan never reduces a balance. Only a real payment, waiver or decrease adjustment changes what you owe.</p></div><div class="settings-card"><h3>3 · Protect the ledger</h3><p class="tx-meta">Enable encryption and save the recovery key outside this device.</p></div></div><div class="form-actions"><button class="btn btn-primary" data-action="finish-onboarding">Got it</button></div>`));}
async function finishOnboarding(){await commit({event:'Onboarding completed',details:'First-run guidance acknowledged',mutate:async s=>{s.settings.onboarded=true;}});closeModal();}
function openGlossary(){const items=[['Creditor','The person, company or organization you owe.'],['Debt record','An original liability entry. It is never silently overwritten.'],['Payment','Money actually paid. It reduces the balance and can be allocated to debt records.'],['Adjustment','A new increase or decrease that corrects or changes liability without rewriting history.'],['Waiver / settlement','A creditor-forgiven amount. It reduces liability but is not counted as cash paid.'],['Reversal','A new opposite entry that cancels the financial effect of an earlier payment, waiver or adjustment.'],['Void','Keeps a mistaken record in history but removes its financial effect. A reason is required.'],['Confirmed','Amount verified from a reliable source.'],['Estimated','Approximate amount that still needs confirmation.'],['Disputed','Amount recorded in the ledger but not accepted as agreed.'],['Effective date','The calendar day the financial event actually happened.'],['Recorded at','The timestamp when you entered it in Ledgerly.']];ui.modal={type:'glossary'};openModal(modalFrame('Help & glossary','Ledgerly uses accounting-style history with simple personal language.',`<div class="ledger-list">${items.map(([a,b])=>`<div class="tx-row"><div class="tx-title">${esc(a)}</div><div class="tx-meta">${esc(b)}</div></div>`).join('')}</div>`),{wide:true});}

async function encodeDraft(payload){return record?.encrypted?{encrypted:true,envelope:await encryptJson(payload,dek)}:{encrypted:false,payload};}
async function decodeDraft(rec){if(!rec)return null;return rec.encrypted?decryptJson(rec.envelope,dek):rec.payload;}
function handleDraftInput(e){const form=e.target.closest('form[data-draft-id]');if(!form||!state)return;clearTimeout(draftTimer);draftTimer=setTimeout(async()=>{try{const values=Object.fromEntries(new FormData(form).entries());const encoded=await encodeDraft({values,savedAt:nowIso(),formId:form.id});await saveDraft({id:form.dataset.draftId,...encoded,updatedAt:nowIso()});}catch{}},350);}
async function restoreFormDraft(form){if(!form?.dataset?.draftId||!state)return;try{const rec=await getDraft(form.dataset.draftId);const draft=await decodeDraft(rec);if(!draft?.values)return;for(const [name,value] of Object.entries(draft.values)){const el=form.elements.namedItem(name);if(!el)continue;if(el.type==='checkbox')el.checked=value==='on'||value===true;else el.value=value;}toast('Unfinished entry restored',`Draft from ${shortDateTime(draft.savedAt)}.`);}catch{}}
async function clearCurrentDraft(){const form=document.querySelector('#modal form[data-draft-id]');if(form?.dataset?.draftId)await deleteDraft(form.dataset.draftId).catch(()=>{});}
